/**
 * Session AL (Part 15, C-DVG-87 / GAP-165): each topic says when its text last changed, read from the repository's history
 * (git blame on this file; the history this checkout holds starts on 1 Nov 2026, so an older topic says "or earlier").
 * Change the date when you change a topic's text; lib/search/help-whats-new.test.ts checks every topic has one.
 */
function Section({id, eyebrow, title, updated, children}: {id: string; eyebrow: string; title: string; updated: string; children: ReactNode}) {
  return <section className="panel help-section" id={id} aria-labelledby={`help-${id}`}>
    <p className="eyebrow">{eyebrow}</p>
    <h2 id={`help-${id}`}>{title}</h2>
    <p className="help-updated">Last updated {updated}</p>
    {children}
    {/* Session AL (P-DV-126, DV-174): a long page; each topic ends with a way back to the topic list. */}
    <p className="help-to-top"><a className="text-link" href="#help-topics">↑ Back to the topics</a></p>
  </section>;
}
function Question({question, children}: {question: string; children: ReactNode}) {
  return <details className="help-question"><summary>{question}</summary><div>{children}</div></details>;
}

/**
 * Help (Session L): plain answers for the friends Alpha, following the owner principle. Static text plus two small
 * client parts (the install guide and "Keep my data on this device"). It makes no request and writes nothing on view.
 */
export function HelpPage() {
  return <div className="help-page">
    <PageHeader titleId="help-title" eyebrow="Help & guides" title="Help." lede="How ZIGoals keeps your plans, and how to get the most out of the Alpha." art={<OrbitArt glyph={HelpGlyph} spin={-26}/>}/>
    {/* Session AL (D-159): the way back to Settings shows only after arriving from Settings. */}
    <HelpBack/>
    <HelpSearch/>
    <HelpTopics topics={TOPICS}/>

    <Section id="getting-started" updated="Nov 1, 2026 or earlier" eyebrow="GETTING STARTED" title="Three small first steps">
      <ol className="help-steps">
        <li><strong>Your first Goal.</strong> In <Link className="text-link" href="/app/goals">Goals</Link>, choose <strong>+ Create a goal</strong>: name it, pick what you are aiming for, and follow the steps.</li>
        <li><strong>Your first Habit.</strong> In <Link className="text-link" href="/app/habits">Habits</Link>, choose <strong>+ New habit</strong>, start from a template or your own title, and tap it each day you do it.</li>
        <li><strong>Quick counters.</strong> In <Link className="text-link" href="/app/health">Health</Link>, <strong>Quick counters</strong> add today&rsquo;s repetitions with one tap, and the Water card in the Diary logs a set amount with one tap (Add 250 mL, or sizes you choose).</li>
      </ol>
      <p>Today brings them together. Want the guided tour again? <Link className="text-link" href="/app/welcome">Show the welcome</Link>.</p>
    </Section>

    <Section id="data-and-sync" updated="Nov 4, 2026" eyebrow="YOUR DATA AND SYNC" title="Where your data lives">
      <h3>Without an account</h3>
      <p>Without an account, your Goals, Habits, Health and Wealth live only on this device, in this browser. Browser storage is not encrypted: anyone who can use this browser profile could read it, so keep your phone and computer locked.</p>
      <h3>With an account (by invitation during the Alpha)</h3>
      {/* Session AL (BN-024, BN-165; P-BN-40): Help described an installation with accounts switched on as if every one had them. */}
      <p><strong>Only where accounts are switched on.</strong> On an installation without them, Settings &rarr; Account &amp; devices says that email access and encrypted sync are not configured, and the account controls named on this page (Devices and sessions, Rotate vault encryption, Remember or Forget this device, Choose what joins your account) do not show. Everything else works on this device as described.</p>
      <p>You sign in with a code sent to your email, and turn on encrypted sync once: it&rsquo;s offered right after you sign in. From then on, every device you unlock stays up to date automatically. No backups or transfers by hand. Turn on encrypted sync on your first device before you start using a second one.</p>
      <p>Your data is end-to-end encrypted on your device before it leaves; nobody else can read it, as long as the app code we serve has not been tampered with. A device you chose to remember can open it too. The server stores that encrypted data plus what it needs to deliver it: your account, record identifiers, sizes, times, and which part of the app a record belongs to. It cannot read your plans, habits or health entries. Health syncs only if you turn it on, separately.</p>
      <h3>Signing in is not recovery</h3>
      <p>Your email code proves it&rsquo;s you. It cannot unlock your data: only your recovery secret can. ZIGoals asks for it when you open your account on a device; a password manager can fill it in. On your own phone or computer you can tick &ldquo;Remember on this device&rdquo;: ZIGoals then opens your account there without asking again, until you lock it or choose Forget this device in Settings. Locking locks every tab of this browser. Don&rsquo;t use it on a shared computer.</p>
    </Section>

    <Section id="recovery-secret" updated="Nov 5, 2026" eyebrow="YOUR RECOVERY SECRET" title="The one thing to keep safe">
      <p>When you turn on encrypted sync, your device creates a long random <strong>recovery secret</strong>. It is the only key to your encrypted data you can write down (a device you chose to remember holds the vault key too), and it is shown only then.</p>
      <p className="fine">The account controls below show in Settings once you are signed in to an account (see Where your data lives).</p>
      <ul className="help-list">
        <li><strong>Keep it in a password manager</strong>, or written down somewhere safe and offline.</li>
        <li><strong>Never share it</strong>: not in screenshots, chats or support emails. We will never ask for it.</li>
        {/* Session AL (BN-165, B-193, BN-024, D-091; COPY_AUDIT, deliberate): each step that needs an account control says so
            in its own line, so no answer reads as a control every installation has. */}
        <li><strong>Lost a device?</strong> With an account only: revoke it under Settings → Devices and sessions, then rotate the vault key (Settings → Rotate vault encryption) so a remembered copy cannot open new records. Sign in on another device and unlock with the secret; sync brings everything back. Without an account there is nothing to revoke: your records were only on that device, so a backup file is what brings them back (see Optional backups).</li>
        <li><strong>Lost the secret, but a device still opens your account?</strong> With an account only: on that device, choose Rotate vault encryption in Settings to get a new secret, and save it.</li>
        <li><strong>Lost the secret and every device that opens your account?</strong> Then the data is gone. Nobody, including us, can unlock it.</li>
      </ul>
    </Section>

    <Section id="install" updated="Nov 1, 2026 or earlier" eyebrow="INSTALL ON IPHONE" title="Install ZIGoals on your iPhone">
      <InstallGuide/>
      <h3>Protect what&rsquo;s on this device</h3>
      <p>Without an account, your data lives only on this device: installing ZIGoals and keeping its data on this device protect it. With an account, you turn encrypted sync on once, and every device you unlock stays up to date automatically. A backup is only an optional extra safety net.</p>
      <h3>Keep my data on this device</h3>
      <KeepData/>
    </Section>

    <Section id="backups" updated="Nov 1, 2026 or earlier" eyebrow="OPTIONAL BACKUPS" title="An extra safety net, never a chore">
      <p>You don&rsquo;t need backups to stay up to date: once sync is on, your devices keep each other current. A backup is just an extra copy you can keep if you like, and the way to move records you already made in Safari into the installed app.</p>
      <ul className="help-list">
        <li><strong>Encrypted backup:</strong> one file protected by its own separate secret. Make or restore one under <Link className="text-link" href="/app/settings#private-vault">Settings → Keep a protected copy</Link>.</li>
        <li><strong>Readable exports</strong> of a single part (the Goals and Wealth, Habits or Health backup) are plain files with your personal data: store them privately.</li>
      </ul>
    </Section>

    <Section id="your-ai" updated="Nov 5, 2026" eyebrow="ZIGi · Your Personal AI Companion" title="Your own AI, page by page">
      <p><strong>ZIGi</strong> is a chat inside ZIGoals that answers with an AI <em>you</em> connect: an API key you pay for, a model running on your own computer, or, if you only have a ChatGPT, Claude, Grok or Gemini subscription, a prompt you copy into that app. It is <strong><Link className="text-link" href="/app/plans">Premium, free during the Alpha</Link></strong>. Set it up in <Link className="text-link" href="/app/settings#your-ai">Settings &rarr; ZIGi &middot; Your Personal AI Companion</Link>; then the ZIGi button sits at the bottom right (above the tabs on a phone), and &#8984;/Ctrl+Shift+Z opens it too (outside a text field), as does Ask ZIGi, the first row of the command menu (&#8984;/Ctrl+K).</p>
      <p>ZIGi is not the Guide. The Guide is ZIGoals&rsquo; own calm note from your records, made on this device with no AI service at all. ZIGi uses your AI; simple questions are answered on this device without one.</p>
      <HelpQuestion id="your-ai-what" question="What does ZIGi send, and to whom?"><p>Only to the provider you connected, straight from your browser: your message, the records your question needs and the page&rsquo;s data as plain text if sharing is on for those areas, your own instructions, and the last few messages within your context budget. Nothing passes through ZIGoals&rsquo; servers and nothing is logged there (ZIGoals hosted, when it is offered to you, is the one exception, and you agree to it first). Sharing starts on for Today, Goals, Habits, Wealth and Help and <strong>off for Health</strong>; Health needs its own switch too. Open the chat and expand &ldquo;What your AI sees&rdquo; for the exact text. Identifiers, wallet addresses, chain details, account and sync data are never included.</p></HelpQuestion>
      <HelpQuestion id="your-ai-writes" question="Can ZIGi change my records?"><p>Not by itself. When you ask it to log or create something, it shows a card that says exactly what would be written and where. You add it, edit it or dismiss it, and you can undo an addition for ten seconds. Money is different: ZIGi can only pre-fill the add-asset form, which you review and save yourself. It can never contribute, allocate, stake, touch a wallet or chain, or change sync, export, deletion or settings. When your records show there is nothing to change (no fast running to stop, a goal already open, a unit already set that way) ZIGi says so instead of showing a card the app would refuse, and each reply names the records that went with your question (&ldquo;Records sent&rdquo;).</p></HelpQuestion>
      <HelpQuestion id="your-ai-cost" question="What does it cost?"><p>ZIGoals bills nothing: nothing is charged during the Alpha. The <Link className="text-link" href="/app/plans">Plans page</Link> shows the one-time prices planned for later, ZIGoals €20 and ZIGoals Premium €50 (Premium adds ZIGi and NOVA&rsquo;s premium features; you still bring your own AI). Placeholder prices · nothing is charged during the Alpha · prices may change. An API key is pay-as-you-go with your provider, who shows you the usage; ZIGi shows the token counts your provider reports under each reply and in Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; Usage, and money only as an estimate from prices you enter yourself, with an optional monthly cap. The reply length is capped (Settings &rarr; Output cap), and ZIGi asks before sending more page data than your context budget. A local model costs nothing to run. On Claude, the unchanging part of ZIGi&rsquo;s prompt is cached by the provider: the same asks cost about four fifths less in input tokens, and the usage counts show cache reads and writes.</p></HelpQuestion>
      <HelpQuestion id="your-ai-subscriptions" question="I pay for ChatGPT, Claude, Grok or Gemini. Can ZIGi use that?"><p>Not directly: those subscriptions have no connection a browser app may use, and ZIGoals will never ask for your password or read your cookies. Choose &ldquo;I only have a subscription&rdquo;: ZIGi writes the question with your page data, you press <strong>Copy for my AI</strong>, open the app and paste. OpenRouter is the one provider with an official sign-in for apps like this one; it gives ZIGoals a key you can see and revoke on OpenRouter.</p></HelpQuestion>
      <HelpQuestion id="your-ai-local" question="How do I use a model on my own computer?"><p>Run Ollama or LM Studio, then choose &ldquo;I run a model on this computer&rdquo; and test the connection. <strong>Ollama</strong> must allow this site: set <code>OLLAMA_ORIGINS=https://alpha.zigoals.app</code> (macOS: <code>launchctl setenv OLLAMA_ORIGINS https://alpha.zigoals.app</code>; Linux: <code>systemctl edit ollama.service</code> with <code>Environment=&quot;OLLAMA_ORIGINS=https://alpha.zigoals.app&quot;</code>; Windows: a user environment variable), then restart it. <strong>LM Studio</strong>: Developer &rarr; Server Settings &rarr; <strong>Enable CORS</strong>. <strong>Chrome 145</strong> and later (and Edge, and Firefox 151 and later) asks once to let this site reach apps and services on this device: allow it. Safari can&rsquo;t reach a model on this computer from a web page. A phone cannot reach a computer&rsquo;s localhost.</p></HelpQuestion>
      <HelpQuestion id="your-ai-keys" question="Where is my key kept?"><p>On this device only, never synced, never exported, never shown back. With &ldquo;Remember on this device&rdquo; it is encrypted at rest with a key that never leaves this browser, which protects against casual reading of the disk or a backup, not against malware on the device. Without it, the key lives in the page and is forgotten when the tab closes. Showcase keeps keys for the session only. Disconnect or &ldquo;Turn off ZIGi&rdquo; removes them; signing out of an account removes that account&rsquo;s remembered keys.</p></HelpQuestion>
      {/* Session Z-Cloud Part 2 and the owner's round 2 (ADR-019 C4–C9, C45): one header row, a clean chat, folded cards. */}
      {/* Session Z-Cloud Part 3 (ADR-019 C12–C19): voice with or without an AI, English and Dutch, tap or hold, read-aloud of spoken replies. */}
      <HelpQuestion id="your-ai-voice" question="Can I talk to ZIGi?"><p>Yes, in English or Dutch, wherever your browser offers speech recognition, with or without an AI connected: without one, ZIGi answers questions in English from your records on this device, and an English line Quick add understands becomes its card for you to save. Tap the microphone by the message box to start and again to stop, or hold it and let go. Hold ZIGi&rsquo;s button to talk from any page, or press &#8984; or Ctrl + Shift + Space; Escape cancels. On an iPhone, a hold on ZIGi&rsquo;s button may only light the microphone: tap it to talk. Your words go to ZIGi when you stop talking, and a reply to a spoken question is read aloud with your device&rsquo;s own voices: never between 22:00 and 08:00, never while muted (the Mute chip by the message box), and it stops when you talk or tap. Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; <strong>Voice: talk to ZIGi</strong> has the language (British or American English, Belgian or Netherlands Dutch, or this device&rsquo;s), &ldquo;Send when I stop talking&rdquo;, &ldquo;Tap ZIGi to talk&rdquo; and &ldquo;Show the microphone&rdquo;. Chrome may send the audio to Google unless on-device recognition is available, and Safari may send it to Apple; ZIGoals never stores it, and the microphone is released the moment you stop. Firefox has no speech recognition: use your keyboard&rsquo;s dictation (the mic on the iPhone keyboard), or type. With an API key from a provider that transcribes, you can choose a recording of up to a minute transcribed by your provider instead. And say things the way you say them: numbers in words (&ldquo;two and a half litres&rdquo;, &ldquo;tienduizend stappen&rdquo;), times (&ldquo;quarter to eight&rdquo;, &ldquo;half acht&rdquo;) and a correction mid-sentence (&ldquo;three glasses, no wait, four&rdquo;): the card takes the last thing you meant, and your words stay on screen exactly as you said them.</p></HelpQuestion>
      <HelpQuestion id="your-ai-honest" question="Does ZIGi give health or money advice?"><p>No. It summarises what you recorded and helps you log; it gives no medical, dietary, financial or investment advice, no targets and no judgement. Food values it estimates are marked &ldquo;AI estimate&rdquo;, and anything it cannot know stays &ldquo;unknown&rdquo;. Every reply is labelled as your AI&rsquo;s answer, not ZIGoals&rsquo;. Your AI can be wrong: check what matters.</p></HelpQuestion>
      <HelpQuestion id="your-ai-data" question="Can I ask ZIGi about my records, like “How many minutes did I meditate this month?”"><p>Yes. ZIGi reads the dates in your question (today, yesterday, this or last week, this or last month, the last 30 days, since a date, between two dates, a named month) in your own time zone, and finds the habit, goal, food or coin you name. Totals, counts, minutes, averages, streaks, best days, progress and &ldquo;when did I last&rdquo; are answered <strong>on this device, with no AI at all</strong>, labelled &ldquo;Answered on your device &middot; no AI used&rdquo;, with the records it used. That works before you connect an AI, and in Showcase. When two things match, ZIGi asks which one you mean instead of guessing; when it does not know, it says so. &ldquo;Ask my AI for more&rdquo; sends the same question with the same records to your AI. Health is only read when its gate is open.</p></HelpQuestion>
      <HelpQuestion id="your-ai-tools" question="How does my AI get the records it needs?"><p>Two ways, both read-only. With <strong>Tools</strong>, your AI asks ZIGi for exactly what it needs (&ldquo;meditation, this month&rdquo;), ZIGi looks it up on this device and sends back only that; the reply shows &ldquo;ZIGi looked at:&rdquo; chips you can open to see the data. With <strong>Attach</strong>, ZIGi picks the records from your question and the page and shows them as chips you can remove before you send. <strong>Automatic</strong> (the default) uses tools where your model takes them and attaches otherwise. Either way only what your switches allow, never on private screens, and changes still come only as cards you confirm. &ldquo;Think deeper&rdquo; asks again with a second model you choose. Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; Advanced.</p></HelpQuestion>
      <HelpQuestion id="your-ai-act" question="What can ZIGi log or plan for me?"><p>Ask in your own words, type <code>/log</code>, or hold the microphone and talk: ZIGi turns one message into cards, for example a breakfast as a meal, a glass of water and a habit check-in, with &ldquo;Add all&rdquo; and one Undo. It can propose foods, recipes, a meal plan, grocery items, counters, check-ins in minutes or amounts, reminders, a goal plan with milestones, a new habit with its reminder, and your weekly intention. Nothing is written until you add a card. With a model that reads images and Health shared, you can add a <strong>photo of a meal</strong>: it goes only with that message to your AI and is never kept; the cards say &ldquo;Estimated by your AI from a photo&rdquo;, and what it cannot know stays unknown. Money stays a pre-filled form you save yourself. ZIGi can also draft a goal of any of the four types (a project counts its milestones), stack one habit after another, change a habit&rsquo;s or a goal&rsquo;s plain fields, note how the day felt for the evening wrap-up, and add a link or a widget to Today; when you correct a proposal, the earlier cards are marked replaced. Confirmed actions are listed under Activity &rarr; Actions by ZIGi. <strong>Auto-accept</strong> (Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; Auto-accept, off by default) lets ZIGi add the kinds you choose without a tap: each addition shows for ten seconds with Undo and is listed under Actions by ZIGi; Health entries only while Health is shared with ZIGi; never weight, fasting or anything about money; a daily cap on top. Every ordinary task in the app is a card now: pause or archive a habit, vacation days, undo a skip, turn a reminder off, close or reopen a goal, edit a diary entry, a planned meal, grocery notes, favourites, counters, targets, the running night, the meditation bell, Today&rsquo;s preset, your links, the weekly review, the evening wrap-up, which pages show, the start page, ZIGi&rsquo;s own look; a deletion opens the app&rsquo;s own confirmation.</p></HelpQuestion>
      <HelpQuestion id="your-ai-alive" question="What does ZIGi&rsquo;s figure do?"><p>ZIGi is drawn by a studio: a still for every state and a short clip for the ones that move (idle, greeting, listening, thinking, speaking, presenting, an insight, attention, sleepy, a calm celebration, an error). The still shows first and the clip loads only when that state shows and ZIGi is on screen. Under <strong>Full</strong> animation ZIGi glances or thinks now and then while idle; <strong>Calm</strong> (the default) keeps the idle clip; <strong>Off</strong>, your device&rsquo;s reduced-motion setting and Motion Off in Settings keep the still. Its feelings follow what the app confirmed, never what a model said: a check-in is a small success, finishing every habit of the day, a streak milestone, a funded goal, a finished meditation or the first night logged is a calm celebration (at most three a day); your AI may suggest one mood per reply from a short list, and the app checks it. <strong>Meet ZIGi</strong> in Settings &rarr; ZIGi &middot; Your Personal AI Companion shows every state with what it means in plain words.</p></HelpQuestion>
      <HelpQuestion id="your-ai-auto" question="Can ZIGi add things without my tap?"><p>Only the kinds you switch on under Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; <strong>Auto-accept</strong> (off by default). ZIGi then adds those cards itself when it proposes them: each shows for ten seconds with Undo and is listed under Activity &rarr; Actions by ZIGi as &ldquo;Added by ZIGi (auto-accept)&rdquo;. Health entries (food, water, sleep, mindful minutes, the mood, steps, measurements, counters, recipes, groceries, planned meals) are automatic only while Health is shared with ZIGi at that moment; weight, fasting and anything about money are always confirmed by you; a daily cap (20 by default) stops the rest, and the chat says so.</p></HelpQuestion>
      <HelpQuestion id="your-ai-notes" question="What does ZIGi know about me?"><p>Only the notes you keep in Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; <strong>What ZIGi knows about me</strong>: goals, preferences, constraints, diet style, schedule, up to 100 notes. ZIGi may suggest one on a &ldquo;Remember this?&rdquo; card; nothing is kept until you confirm. Notes go to your AI only while &ldquo;Use my notes&rdquo; is on, as an &ldquo;About me&rdquo; chip you see first; notes about health or your diet style only while Health is shared with ZIGi. Delete one or all at any time; they are in Export everything and never synced.</p></HelpQuestion>
      <HelpQuestion id="your-ai-pack" question="What is the context pack?"><p>A file of your records for your AI&rsquo;s own project knowledge (Claude Projects, ChatGPT Projects, Gemini Gems and similar), so an AI you use outside ZIGoals knows your goals, habits and wealth between chats. Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; <strong>Context pack for my AI</strong>, or <code>/pack</code>: choose the areas and the period (90 days unless you change it), see the preview, then download it (Markdown or JSON) or copy it. Health is in it only with its gate open and its own box ticked. It carries no account data, ids, keys, wallet addresses or recovery data. <strong>It is not encrypted:</strong> anyone and any AI you give it to can read it. A weekly &ldquo;new context pack&rdquo; reminder is optional.</p></HelpQuestion>
      <HelpQuestion id="your-ai-suggestions" question="Where do ZIGi’s chips, brief and patterns come from?"><p>From your records, worked out on this device; nothing is sent to make them. The <strong>Suggestions</strong> chip by the message box opens them: <strong>Ideas</strong>, chips that change daily and can be dismissed; <strong>Your day</strong>, a short brief (what is due, one win from yesterday, one focus), your week and patterns; and <strong>Yours</strong>: a question you asked three times within 30 days becomes your own suggestion, at most 12 shown, pinned first, each with Pin and Remove. Yours are kept on this device only, never synced, and sent only when you tap one; a question about Health is kept only while Health is shared with ZIGi. Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; What ZIGi knows about me lists them with &ldquo;Forget all&rdquo;, and Turn off ZIGi removes them. A quiet brief card can show on Today while ZIGi is connected. &ldquo;Ask ZIGi&rdquo; next to a number puts that number in the message box; nothing is sent before you press Send. Patterns appear only with enough days, are &ldquo;a pattern, not proof&rdquo;, and never medical or financial advice. <code>/review</code> walks through your week with you.</p></HelpQuestion>
      <HelpQuestion id="your-ai-commands" question="Which slash commands and shortcuts does ZIGi know?"><p>Type <code>/</code> in the message box for the list: <code>/log</code> logs what you did, ate or drank as cards; <code>/ask</code> sends a question straight to your AI; <code>/plan</code> plans a goal or a habit as cards; <code>/review</code> goes through your week on this device; <code>/pack</code> opens the context pack; <code>/insights</code> shows patterns in your records; <code>/remember</code> proposes a note for What ZIGi knows about me; <code>/help</code> lists them. Press <kbd>?</kbd> outside the message box for the keyboard shortcuts; &#8984;/Ctrl+Shift+Z opens and closes ZIGi outside a text field (in one it stays Redo), and &#8984;/Ctrl+K opens the command menu: pages, actions and your recent tasks, with Ask ZIGi as its first row.</p></HelpQuestion>
      <HelpQuestion id="your-ai-mini-window" question="What is ZIGi’s mini window?"><p>On a computer with Chrome or Edge 116 and later, or Firefox 151 and later, <strong>Pop out</strong> in ZIGi&rsquo;s panel opens the same chat in a small window that stays on top of your other apps while ZIGoals&rsquo; tab is open. &ldquo;Back to tab&rdquo; returns it; closing the tab closes it. When the tab shows a private screen, the window blurs and waits. Safari and phones do not offer it, so the button is not shown there. A companion that lives on your desktop without the tab would need a native app, which ZIGoals does not have.</p></HelpQuestion>
      {/* Session AL (N-LA-07, P-LA-31): which screens pause ZIGi, from components/ai/use-sensitive-screen.ts SENSITIVE_SELECTOR. */}
      <HelpQuestion id="your-ai-private" question="Which screens pause ZIGi, and why?"><p>ZIGi reads the page you are on to answer about it. On a private screen it reads nothing from the page and its button is hidden; its mini window says &ldquo;Paused while a private screen is open in the tab.&rdquo; It comes back as soon as you leave. The private screens are:</p><ul className="help-list"><li><strong>the Checklist</strong>, and any other window over the page: a review before you sign in your wallet, the phone&rsquo;s More menu, a confirmation;</li><li><strong>the screen cover</strong> while it asks for your PIN;</li><li><strong>Settings &rarr; your account</strong> while it shows a sign-in code, a password or vault secret, your recovery secret or the account deletion section, and its email field while you type in it;</li><li><strong>any field for a password, a one-time code, a PIN, a key or a recovery phrase</strong>, anywhere, while you type in it.</li></ul><p>Why: these are the moments when what is on the screen could be a secret, or when you are in the middle of something that needs your full attention. The pause is about the screen, not your records: from another page you can still ask ZIGi about your Checklist (&ldquo;Show my checklist&rdquo;), and ZIGi reads those records only as it reads any other.</p></HelpQuestion>
      <HelpQuestion id="your-ai-knock" question="Can ZIGi knock when a reminder is due?"><p>If you turn it on: ZIGi asks you once, or use &ldquo;Knock when a reminder is due&rdquo; in ZIGi&rsquo;s look and feel. When a habit, your water or one of ZIGi&rsquo;s weekly reminders is due, ZIGi peeks out above its button and knocks once, with <strong>Do it now</strong>, <strong>Snooze</strong> (15 minutes, 1 hour or tonight) and <strong>Not today</strong>. At most three a day, never between 22:00 and 08:00, never on private screens or while ZIGi is hidden, never on Today (the reminder has its own card there), and no sound. ZIGi&rsquo;s weekly reminders are listed, with Remove, under Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; Reminders.</p></HelpQuestion>
      <HelpQuestion id="your-ai-agents" question="Can an AI agent in my browser use ZIGoals?"><p>Only if your browser offers tools to its AI agents (WebMCP, an early Chrome feature; today only with <code>chrome://flags/#enable-webmcp-testing</code> turned on) <strong>and</strong> you turn on &ldquo;Let browser AI agents use ZIGoals tools&rdquo; in Settings &rarr; ZIGi &middot; Your Personal AI Companion. It is off by default and the card only shows in such a browser. An agent then gets ZIGi&rsquo;s read-only lookups under the same switches as your AI, and can propose changes, which appear as cards in ZIGi&rsquo;s panel for you to add. Every request shows at once in a ZIGi notice with exactly what went back and &ldquo;Turn off browser agents&rdquo;. Nothing on Settings or private screens.</p></HelpQuestion>
      <HelpQuestion id="your-ai-which-setup" question="Which setup fits me?"><p>Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; <strong>Which setup fits me?</strong> asks three or four questions (what you have today, where you use ZIGoals, what matters most to you and, on a computer, its memory) and suggests one way, with honest pros and cons and the exact steps: your subscription through Copy for my AI, a model on your computer (Ollama or LM Studio), an API key with a spending limit set at your provider first, or Chrome&rsquo;s on-device model (and ZIGoals hosted, once it is offered to you). It is worked out on this device; nothing is sent.</p></HelpQuestion>
      <HelpQuestion id="your-ai-on-device" question="What is Chrome’s on-device model?"><p>A small model inside Chrome on some computers (Chrome 148 and later on Windows, macOS, Linux and some Chromebooks; not on phones). Where Chrome has it, Settings shows a card for it; Chrome downloads the model only when you press its button there, a one-time download that needs about 22 GB of free space. Then, while no AI is connected, it words ZIGi&rsquo;s brief, helps ZIGi understand a question, and gives short general answers labelled &ldquo;Answered by Chrome&rsquo;s on-device model&rdquo;. It gets only your words, never your records, and nothing leaves the computer.</p></HelpQuestion>
      <HelpQuestion id="your-ai-hosted" question="What is hosted ZIGoals?"><p>An AI that ZIGoals runs and pays for, for invited accounts during the Alpha, so you need no key or app of your own. It is <strong>not available yet</strong>; when it is offered to you, it appears in Settings &rarr; ZIGi &middot; Your Personal AI Companion. Before first use you read what passes through and agree: your messages and the records ZIGi attaches go through ZIGoals&rsquo; server to the AI provider named there, which writes the reply. ZIGoals stores and logs none of it and keeps only counts for the daily limit. Health goes only if you tick its own box and the Health gate is open. Replies say &ldquo;Answer from &lt;provider&gt; via ZIGoals hosted&rdquo;. On Claude it is called <strong>ZIGoals AI &middot; powered by Claude</strong>: replies say &ldquo;Answer from ZIGoals AI &middot; powered by Claude&rdquo;, and Settings shows what is left of your own allowance, messages and dollars a day and a month. Stop using it at any time.</p></HelpQuestion>
      <HelpQuestion id="your-ai-look" question="Can I change how ZIGi looks?"><p>Yes: <strong>Customize</strong> in ZIGi&rsquo;s &ldquo;&#8943;&rdquo; menu, or ZIGi&rsquo;s look and feel in Settings. Choose the look, the animation (Calm by default, Full or Off), the side, the size, the greeting and the edge tab. Reduced motion and Motion Off always win: ZIGi then holds still. <Link className="text-link" href="/app/zigi">Meet ZIGi</Link> shows all its moods.</p></HelpQuestion>
      <HelpQuestion id="your-ai-off" question="How do I turn ZIGi off, or hide the button?"><p>Settings &rarr; ZIGi &middot; Your Personal AI Companion &rarr; Advanced &rarr; <strong>Turn off ZIGi</strong> removes the keys and your own suggestions from this device and resets the switches; tick &ldquo;Also delete all chats&rdquo; to remove the conversations too. The small arrow under the button, <strong>Hide ZIGi</strong>, hides it (undo for ten seconds); the &ldquo;Show ZIGi&rdquo; tab at the edge of the screen, &ldquo;Show the ZIGi button&rdquo; in Settings, or &ldquo;Show ZIGi again&rdquo; in a phone&rsquo;s More sheet brings it back. You can turn the edge tab off in ZIGi&rsquo;s look and feel.</p></HelpQuestion>
    </Section>

    {/* Owner follow-up 2 (N, B, T): NOVA, notes and tasks, task-shaped. */}
    <Section id="nova" updated="Nov 4, 2026" eyebrow="NOVA, NOTES AND TASKS" title="Your command center, your notes and your day">
      {/* Session AL (O3, O4; shell lane request): where the assistant and the small apps live on each kind of screen. */}
      <p><strong>Where to find them.</strong> On a phone or a tablet, ZIGi, NOVA, the Checklist, Tasks, Notes, the Journal, the Agenda, Earn and Music are in <strong>Apps &amp; extras</strong> (the top bar on a phone, the rail on a tablet), each one while it is switched on under Settings &rarr; Your pages &amp; buttons. On a computer, NOVA, Tasks, Notes, the Journal and the Agenda are in the sidebar&rsquo;s <strong>Apps</strong> group, and ZIGi, the Earn dock, Music and the Checklist float at the edge.</p>
      <HelpQuestion id="nova-what" question="What is NOVA?"><p>NOVA is your private command center on top of ZIGoals: a full-screen view of your day, your four pillars, your agents and every feature one tap away (<Link href="/app/nova">open NOVA</Link>, ⌘/Ctrl + J from any page, or NOVA in the menu). It runs on ZIGi&rsquo;s engine, so NOVA and ZIGi share one history and one memory on this device, hand a conversation to each other (&ldquo;Continue in NOVA&rdquo;, &ldquo;Ask ZIGi about a page&rdquo;) and can work a task together. Without a model NOVA answers on the device from your own records. You can make ZIGoals open on NOVA in NOVA &rarr; Customize the view &rarr; Make it yours.</p><p>While NOVA hands a page task to ZIGi, both appear side by side on NOVA&rsquo;s dashboard with the step they are on; every change still comes as a card you confirm. &ldquo;Running now&rdquo; shows what is running on this device (a Pomodoro, a meditation, a habit timer, a fast, a night in bed) with its time and a link to where it ends.</p></HelpQuestion>
      <HelpQuestion id="nova-brain" question="How do I give NOVA a brain, and do my ChatGPT or Claude subscriptions work?"><p>Follow <Link href="/app/nova/setup">Build your own NOVA</Link>. Recommended: a local model on your own computer (Ollama, LM Studio or llama.cpp), with copyable steps for macOS, Windows and Linux and a live test that names the model it found; nothing leaves your computer. Chrome 145 and later, Edge and Firefox 151 and later ask once to let this site reach apps on this device: allow it. Safari can&rsquo;t reach a model on your computer from a web page, and a phone can&rsquo;t reach your computer&rsquo;s models. You can also use your own API key (sealed on this device, sent only to that provider) or sign in with OpenRouter. ChatGPT, Claude, Gemini and Grok subscriptions don&rsquo;t include access for other apps, so they can&rsquo;t sign in here (Claude Max, Ultra and Team include monthly API credits, used through an ordinary key). Gemini&rsquo;s free tier isn&rsquo;t offered in the EEA, Switzerland or the UK.</p></HelpQuestion>
      <HelpQuestion id="nova-privacy" question="What do Strict, Guarded and Relaxed mean?"><p>Your privacy mode decides what may leave your device. <strong>Strict</strong> (recommended): only a local model, nothing to a cloud model (including Ollama models that run in Ollama&rsquo;s cloud). <strong>Guarded</strong>: a cloud model is allowed, but secrets, account and card numbers, IBANs, wallet addresses, e-mails, phone numbers, street addresses, names and exact amounts are removed or rounded first, and you see exactly what will be sent before it goes. <strong>Relaxed</strong>: the areas you allowed in NOVA &rarr; Permissions are sent as they are. Health, Notes and Journal stay off until you turn them on, and &ldquo;What NOVA can see&rdquo; shows the exact text.</p></HelpQuestion>
      <HelpQuestion id="nova-hermes" question="Can I connect my own Hermes Agent?"><p>Yes. <Link href="/app/nova/hermes">Connect your Hermes Agent</Link> walks you through installing Hermes Agent (by Nous Research; <a href="https://hermes-agent.nousresearch.com/docs">its docs</a>), turning on its API server with a key you make, allowing this site in its CORS setting and testing the gateway. Hermes can be NOVA&rsquo;s brain, or an agent NOVA asks (&ldquo;Ask my Hermes&rdquo;). It runs on your computer, but it may use a cloud model and its own tools, so NOVA treats it as Guarded until you confirm it uses a local model. Anything it suggests for ZIGoals comes back as a card you confirm; it never moves money. ZIGoals has no partnership with Nous Research and never sees, stores or relays what you send to your Hermes.</p></HelpQuestion>
      <HelpQuestion id="nova-yours" question="How do I make NOVA mine, and what does Share my NOVA setup include?"><p>In NOVA &rarr; Customize the view: the layout (Orbit, Bento, Focus, Minimal), an accent, which widgets float on the rings and their sizes, NOVA&rsquo;s name and avatar (the orb or ZIGi), what NOVA calls you, your own instructions, the quick-access order, the side panels and single-key shortcuts. &ldquo;Share my NOVA setup&rdquo; makes a small file and a picture with only the arrangement and your workflows&rsquo; names and steps: never your records, your name, your instructions, chats or memory. An import shows a preview first and can be undone.</p><p>In View controls &rarr; On the stage you can add Tasks (today&rsquo;s tasks, overdue ones carried over, your goals&rsquo; next actions: tick with Undo, or add one for today) and Focus (start a Pomodoro; while it runs anywhere, NOVA shows the time left). The Activity panel lists what NOVA and ZIGi changed, with Undo, and Models lets briefs and workflows use a different model from the chat.</p></HelpQuestion>
      <HelpQuestion id="nova-briefs" question="What are NOVA's briefs, workflows and memory?"><p>NOVA writes a morning brief and an evening recap from your own records, on this device; a model may only reword one when you ask, and never changes a number. Eight workflows (review your week, plan meals and the grocery list, where your money went, what affects your sleep, and more) show every step as they run, and every change is a card you add or dismiss, with Undo; save your own versions. NOVA and ZIGi share one memory: only what you accept, with where it came from and its date, never about your health while Health isn&rsquo;t shared. The cost meter is an estimate; local models are free, on your device, and a daily cap can ask you first.</p></HelpQuestion>
      <HelpQuestion id="nova-safety" question="When does NOVA never add a card on its own, and what about imported workflows?"><p>A card is never added without your tap when the answer used your notes, an imported calendar or your journal, came from your Hermes Agent, or answered text you pasted, even for kinds you let ZIGi add on its own; money never is. An imported workflow shows its instruction word for word before its first run, and an instruction with a link or command-like words is replaced by the template&rsquo;s own. A lab-sheet or receipt photo is shown with where it goes before anything is sent.</p></HelpQuestion>
      <HelpQuestion id="ak-unkept-chat" question="Can I have a chat that is not kept?"><p>Yes: &ldquo;Don&rsquo;t keep this chat&rdquo; in ZIGi&rsquo;s &#8943; menu, on NOVA&rsquo;s chat bar, or at the start of a new chat. Nothing of that conversation is saved on this device: not in History or Conversations, not in what ZIGi knows about you, and no card outcome or suggestion. It is gone when you close it or start a new chat. Your privacy mode and every other setting still apply, and the message still goes to the AI you chose.</p></HelpQuestion>
      <HelpQuestion id="notes-what" question="How do notes work?"><p><Link href="/app/notes">Notes</Link>: capture a thought (type, speak or add a photo) from Quick add, the search palette, NOVA or the &ldquo;Capture a note&rdquo; shortcut; it waits in the inbox until you file it into a day, a note, a goal or a habit. Each day&rsquo;s note shows that day&rsquo;s habits, Health logs, workouts, money entries and contributions as links. Write [[ to link a note, goal or habit; each one lists the notes that link to it. The graph shows them as a star system, or as a list. Export as a ZIP of Markdown files for Obsidian, or import .md files or a ZIP; nothing in a file is ever run. Everything stays on this device.</p><p>&ldquo;Ask about my notes&rdquo; on the Notes page sends your question to NOVA. NOVA reads your notes only with Notes on in NOVA &rarr; Permissions (off by default), in your privacy mode, with your own model; without a model, Search finds words on this device.</p></HelpQuestion>
      <HelpQuestion id="tasks-what" question="How do tasks, calendar import and Pomodoro work?"><p><Link href="/app/tasks">Tasks</Link> are one-off things to do and your goals&rsquo; next actions, each with a priority, and a day and time if it has them; tasks with a day appear on your Agenda, and you tick them there or on Tasks, with Undo (the Checklist stays your daily path). On the Agenda, &ldquo;Import a calendar&rdquo; reads an .ics file from your calendar app on this device: only titles, days, times and repeats are kept, read-only; import again to update, remove it any time. Focus sessions have a Pomodoro mode (focus blocks and breaks of your lengths, an optional focus sound), also started from a task; a finished run can tick its task, with Undo.</p></HelpQuestion>
      {/* Session AP (owner-approved feature list): five answers, each saying what is stored and what is only worked out. */}
      <HelpQuestion id="ap-hour-grid" question="Can I plan my day hour by hour?"><p>Yes. In the <Link href="/app/agenda">Agenda</Link>, choose Day, then <strong>By the hour</strong>. Drag a task to an hour, or use its &ldquo;Move to&hellip;&rdquo; to pick a time with the keyboard: the task keeps that day and time, with Undo. Habits, imported events and the rest stay at their own time and are not moved there. Each day says its load: how many of its items have a set time.</p></HelpQuestion>
      <HelpQuestion id="ap-evening-someday" question="What are This evening and Someday in Tasks?"><p>Two lists in <Link href="/app/tasks">Tasks</Link>. <strong>This evening</strong> is for tonight only: tomorrow each task is back in its usual place, and its day is never changed. <strong>Someday</strong> holds tasks with no day that can wait; give one a day and it leaves Someday. Both are kept on this device beside your tasks, are in Export everything, and are not synced.</p></HelpQuestion>
      <HelpQuestion id="ap-matrix" question="What is the Priority matrix?"><p>A view of Tasks in four boxes. Urgent means overdue or due within 2 days; important means priority P1 or P2. Move a card to the box beside it, by dragging it or with its button: only its priority changes (P1, P2 or P3), never its day. To make a task urgent or not, change its day. Nothing new is stored.</p></HelpQuestion>
      <HelpQuestion id="ap-journal-numbers" question="How are my journal streak and word counts worked out?"><p>From your entries on this device, each time you open the <Link href="/app/journal">Journal</Link>; nothing extra is stored. Each entry shows its words. The writing streak counts the days in a row with at least one entry, up to today, and a day you have not written yet does not break it until it ends. Words this year add up the entries dated this year.</p></HelpQuestion>
      <HelpQuestion id="ap-countdowns" question="How do I count down the days to something?"><p>On Today, choose Customize Today, then under &ldquo;Cards kept on this device&rdquo; turn on <strong>Days until</strong> and add a name, a date and an optional note (up to 50). Each says &ldquo;In 12 days&rdquo;, &ldquo;Tomorrow&rdquo; or &ldquo;Today&rdquo;, and also shows on that day in your Agenda. Once its day has passed it moves to Passed and says how many days ago. They stay on this device, are in Export everything, and are not synced.</p></HelpQuestion>
    </Section>
    {/* Session AL (BN-025): the opt-in pages had no topic of their own; their answers were only in the release notes. */}
    <Section id="more-pages" updated="Nov 5, 2026" eyebrow="MORE PAGES" title="Earn, Staking, Governance, Ecosystem and Chess">
      <p>These pages are off on a new device, so a first look stays simple. Settings &rarr; <Link className="text-link" href="/app/settings#your-pages">Your pages &amp; buttons</Link> shows each one, and each keeps its own switch. A hidden page still opens from a link.</p>
      <HelpQuestion id="al-more-pages" question="Where are Earn, Staking, Governance and Ecosystem?"><p>Switch one on in Settings &rarr; Your pages &amp; buttons. Turning on any money and chain page (Earn, Markets, Staking, Portfolio, Ecosystem or Governance) tells ZIGoals you use ZIGChain, so the others show too, along with their Settings (Wallet &amp; network, the Earn dock, validator alerts); hide any of them again with its own switch. Governance stays off until you switch it on, and it shows while Staking shows. {/* Session AL (P-TK-52, TK-146) */}Reward goals, which count your unclaimed staking rewards, appear in <strong>+ Create a goal</strong> once ZIGoals knows you use ZIGChain. Erase everything returns these switches to how a new device starts.</p><p>More about each: <a className="text-link" href="#help-af-earn">the Earn page</a>, <a className="text-link" href="#help-af-staking">staking in your own wallet</a> and <a className="text-link" href="#help-af-governance">voting on proposals</a>.</p></HelpQuestion>
      <HelpQuestion id="al-wallets" question="Can I rename or remove a wallet I track?"><p>Yes. Staking lists every public wallet you track, under the totals, and so does Settings &rarr; Wallet &amp; network. Rename gives it a name of your own, kept on this device. Remove stops reading it here (with Undo); a wallet that still funds a Goal stays until you remove that allocation on the Goal. Tracking never gave ZIGoals any power over the wallet, so removing it changes nothing on the chain.</p></HelpQuestion>
      {/* Session AL fourth pass (C-DVG-71): what ZIGoals signs with, said plainly. */}
      <HelpQuestion id="al-ledger" question="Can I stake with a Ledger, or from a multisig account?"><p>A Ledger, yes: connect it in Keplr as usual. ZIGoals asks Keplr for the signer that fits (the Ledger&rsquo;s own way of signing when a Ledger is connected), shows &ldquo;Ledger&rdquo; beside your address, and every action is still signed on the device itself. A multisig account, no: a transaction that several keys must sign is not something ZIGoals builds, so use your multisig tool for it. Wallets of other chains can still be linked read only, from the wallet menu, so Wealth shows them.</p></HelpQuestion>
      <HelpQuestion id="al-ecosystem" question="What is the Ecosystem page?"><p>A directory of projects on ZIGChain: what each does, its category and status, the sources it was checked against and when. Search and the category chips narrow the list. Links open the project&rsquo;s own site in a new tab. Being listed is not an endorsement, and nothing here is advice.</p></HelpQuestion>
      <HelpQuestion id="al-chess" question="What does the Chess page do?"><p>Add your public Lichess or Chess.com username and ZIGoals reads your public ratings and recent games; it never needs a password for that. You can set rating goals (a whole number from 100 to 4000) and open the daily puzzle. Playing a game happens on Lichess, after you sign in there. Chess is off until you switch it on in Settings &rarr; Your pages &amp; buttons.</p></HelpQuestion>
    </Section>

    <Section id="questions" updated="Nov 14, 2026" eyebrow="QUESTIONS" title="Good to know about the Alpha">
      <Question question="Is any of this real money?"><p>Almost never. Your Goals, Wealth and Portfolio records are what you enter and local simulations, and practice-network tokens have no value. The one exception is staking: when you choose the real network on the Staking page, the stake, unstake, move or claim you review and sign in your own wallet uses real ZIG. ZIGoals never holds keys, and nothing is bought, sold or sent by ZIGoals.</p></Question>
      <Question question="Are my Goals on the blockchain?"><p>Not yet. The on-chain Goal contract is not deployed, so Goals stay in this app.</p></Question>
      <Question question="Where do prices come from?"><p>Automatic prices come from CoinGecko and are labelled with their source. ZIGoals asks only about the public assets you choose, never your amounts, Goals or wallet. If automatic prices are unavailable, the app says so and your own values keep working: a value you enter yourself is labelled as a manual value, never shown as a live quote.</p></Question>
      <Question question="Can I look up a food by its barcode?"><p>When product lookup is available, yes: in Health&rsquo;s Diary, open &ldquo;Scan or look up a food barcode&rdquo;. Only the barcode number is sent, through ZIGoals to Open Food Facts; the camera picture stays on your device. If the live camera is blocked or missing, you can take one photo of the barcode instead; it is read on your device too. When lookups are busy, the button waits for the time shown and then works again. If lookup is unavailable or a product isn&rsquo;t found, add the food yourself in Foods &amp; recipes.</p></Question>
      <Question question="Is my data encrypted on this device?"><p>No. Browser storage isn&rsquo;t encrypted, so lock your device. With encrypted sync, your data is encrypted on your device before it leaves.</p><p>The whole picture, in plain words: <a className="text-link" href="https://zigoals.app/privacy.html" target="_blank" rel="noopener noreferrer">Privacy</a> and <a className="text-link" href="https://zigoals.app/terms.html" target="_blank" rel="noopener noreferrer">Terms</a> (on zigoals.app; they open in a new tab).</p></Question>
      <Question question="I asked for a sign-in code and none arrived"><p>During the friends Alpha, only invited email addresses can sign in, and ZIGoals answers every code request the same way, so it never tells anyone which addresses are invited. If no code arrives: wait a minute and check your spam folder; make sure you typed the address your invite went to; then try again later, because codes can be held back when many are sent at once. If it says &ldquo;Sign-in codes are paused for today&rdquo;, the Alpha&rsquo;s daily limit on code emails is reached for everyone: try again tomorrow (after midnight UTC); a code you already have still works. Still nothing? Ask the person who invited you, or write to <a className="text-link" href="mailto:contact@zigoals.app">contact@zigoals.app</a>. Nothing on this device changes while you wait: your local records stay where they are.</p></Question>
      <Question question="Sync says &ldquo;Sync needs attention&rdquo;. Did I lose something?"><p>No. Your changes are kept on this device. When sync found two versions it won&rsquo;t merge by itself, it keeps both until you choose: open <Link className="text-link" href="/app/settings#encrypted-sync">Settings → Account &amp; devices</Link> (Account &amp; sync on a phone), unlock, and choose &ldquo;Review conflicting account records&rdquo;.</p></Question>
      {SYNC_WRITES && <Question question="Can my Portfolio sync too?"><p>Yes, if you choose: in Settings, under account sync, tick &ldquo;Also sync my Portfolio (optional)&rdquo;. An encrypted copy of your whole Portfolio then travels with your account, separate from your other records, and never feeds Wealth or Goals. If it changed on two devices, ZIGoals asks which one to keep. After you change your vault key, open ZIGoals on a device that has your Portfolio so it can upload it again.</p></Question>}
      {/* Session Y (ADR-018 Y40): this release's small changes, each linkable from What's new. */}
      <HelpQuestion id="y-vacation" question="Can I end a vacation early?"><p>Yes. At the top of Habits, Vacation lists the vacation days still ahead as stretches, each with its habits and its own Clear: it removes those planned skips from today on. Days already past keep theirs, so your history stays as it was.</p></HelpQuestion>
      <HelpQuestion id="y-minus" question="I tapped &ldquo;+&rdquo; once too often. Can I take it back?"><p>Yes: every measured habit (a count, minutes, an amount or your own unit) has &ldquo;&minus;&rdquo; beside &ldquo;+&rdquo;. It takes one off, never goes below zero, and is greyed out at zero. If it takes a day that was ticked off automatically below its target, that automatic tick is undone too, as &ldquo;Undo completion&rdquo; does.</p></HelpQuestion>
      <HelpQuestion id="y-unit" question="Can I change an asset&rsquo;s unit?"><p>A precious metal&rsquo;s weight unit (grams, kilograms or troy ounces), in its editor in Wealth, while nothing recorded counts in that unit yet: no market link, no Goal counting or funded by it, and no recorded value or quantity history. The quantity you enter, in the new unit, replaces the one you added it with. Wealth records the value of every asset that has one each day, so in practice a metal you added with a value keeps its unit, and the editor says why in one sentence. Other assets&rsquo; units are their ticker or currency: add a new asset instead.</p></HelpQuestion>
      <HelpQuestion id="y-sync" question="Sync says the cloud has an older copy, or none. Did I lose something?"><p>No. Nothing on this device was changed, and your records stay readable and exportable. It can happen when the sync service was restored from an earlier copy. With an older copy, sync stops rather than go back in time: try again later, or confirm and choose &ldquo;Re-link this device&rdquo; to sync with the copy the cloud has now (anything that differs goes through the usual review). With no copy, ZIGoals never quietly starts over: a new vault needs your confirmation. Sections you deleted from the cloud stay held for your review either way. After you restore your Health section, Health sync stays off in this tab until you tick &ldquo;Sync my Health records with this account&rdquo;.</p></HelpQuestion>
      {/* Session Z-Cloud (ADR-019 C21–C31): this release's visible changes, each linkable from What's new. */}
      <HelpQuestion id="z-delete-habit" question="Can I delete a habit for good?"><p>Yes, once it is archived: in Habits, choose <strong>Archived</strong>, and the habit&rsquo;s card has &ldquo;Delete for good&hellip;&rdquo;. Type its name and confirm. Its name, notes and every check-in go, on every device you sync, Goals and Health no longer use it, and Export everything leaves it out. Its settings (type, unit, target, schedule) stay in your records without its name, because older copies of ZIGoals need them to keep syncing; an older copy shows it as an archived &ldquo;Deleted habit&rdquo; with no history. Older protected copies, and ZIGi&rsquo;s chats and notes on this device, keep what they already hold. You can undo for ten seconds. A habit whose archive starts on a later day offers it from that day.</p></HelpQuestion>
      {/* Session AL (X3-27, AL-HELP-006): the answer starts with the notice's own words (components/shell.tsx networkLabel,
          components/shell/alpha-notice.tsx), so what Help quotes is what the top of the page shows. */}
      <HelpQuestion id="z-alpha" question="What does the notice at the top mean?"><p>The notice reads <strong>PUBLIC ALPHA</strong> &ldquo;Your records stay in this browser and are not a backup.&rdquo; If you chose the crypto tools, its label reads &ldquo;PUBLIC ALPHA &middot; NOTHING MOVES UNLESS YOU SIGN&rdquo; and it adds that staking and votes sign in your own wallet. <strong>Practice money (no real value) &middot; Public Alpha:</strong> where a wallet shows, what you see is a local simulation plus an optional wallet connection; nothing is placed onchain for you, and the only things you can sign are staking steps and votes, in your own wallet after a review screen. <strong>Your records stay in this browser:</strong> they are private to this browser profile and are not a backup &mdash; make one in Settings. Contract execution is disabled on this Alpha; the project is independent and unaudited, and its only strategy is idle. Never share secrets, private backups or wallet details. After you close the notice, the same facts stay in Settings &rarr; Your data and in &ldquo;About this Alpha&rdquo; below.</p></HelpQuestion>
      <HelpQuestion id="z-about" question="About this Alpha"><p>Everything this Alpha says about itself, in one place: <strong>Public Alpha &middot; nothing moves unless you sign.</strong> Staking and votes sign in your own wallet (practice or real, your choice). Nothing else moves, and ZIGoals never holds keys. Each signature follows a review screen, and contract execution is disabled. {/* Session AK P2 (RELEASE_REVIEW_2 R2-7; TIER 3 public-safety labels): the notice's sentence, word for word; until the chain is chosen the notice links here instead of showing it. */}Your records stay in this browser, and browser storage is not a backup: make one in Settings. ZIGoals is an independent project and an unaudited alpha whose only strategy is idle. Never share secrets, private backups or wallet details. The Showcase&rsquo;s records are fictional and stay in its tab. The live version of these facts &mdash; your mode (local simulation or a Keplr connection), where your records are stored and synced, and the build environment &mdash; is in Settings &rarr; Your data and in Settings&rsquo; &ldquo;About this alpha&rdquo; panel; the first visit also shows them in the notice at the top (until you choose the crypto tools, the notice says only where your records stay, and its More opens this answer). Money and wallet actions keep their own labels where they happen (Staking, Portfolio, a goal&rsquo;s page, Connect Keplr).</p></HelpQuestion>
      <HelpQuestion id="z-have" question="What is &ldquo;What you have&rdquo; in Wealth?"><p>Everything you track in Wealth, in one list: your assets, accounts and debts, with one row of chips &mdash; All, Accounts, Debts, Assets, each asset class and Needs attention &mdash; and how many of each. Each asset keeps its card (value, quantity, price, Goals, source and its actions) and each account or debt its row (balance, Update balance, Record a payment, Edit), with the net worth per currency above them. Portfolio is linked. Nothing about your records changes.</p></HelpQuestion>
      <HelpQuestion id="z-units" question="Can I see my weight in pounds and water in fluid ounces?"><p>Yes: Health &rarr; Journal settings &rarr; Days and units. Weight then reads in pounds to one decimal and water in US fluid ounces, in Health, on Today and in the evening wrap-up. Only what you see changes: your records stay in kilograms and millilitres, and each water entry still reads in the unit you recorded it in.</p></HelpQuestion>
      {/* Session AA-Cloud (ADR-021): this release's visible changes, each linkable from What's new. */}
      <HelpQuestion id="aa-order" question="Why are my pages in a different order?"><p>Each page now starts with what matters most: Today opens with your focus (habits due, the next goal step, water, a fast or last night), then your widgets in small groups, then For you, then Updates and summaries. Goals, Wealth, Markets, Portfolio, Staking, Activity and Settings were put in order the same way. Nothing was removed. If you arranged a page yourself, your own order is kept: only the default changed. <strong>Customize Today</strong>, or the lock button on another page (&ldquo;Unlock layout to rearrange&rdquo;), moves cards.</p></HelpQuestion>
      <HelpQuestion id="aa-goals" question="What are life areas, the balance wheel and the vision board?"><p>Give a goal a life area (Health, Habits &amp; Mind, Wealth, Relationships, Career, Learning, Fun, or your own) on its page or while creating it. <strong>Life balance</strong> on Goals draws a wheel of how each area moved this month, from your goals, habits and Health records; an area with nothing known says so and is never counted as zero. The <strong>Vision board</strong> view shows each goal with its picture: a colour and an emoji, or a photo made smaller on this device. A goal can also keep why it matters, what might get in the way and an if-then plan; it can sit under a bigger goal (Goals shows the tree); and <strong>Keep an average</strong> follows a number over time, like sleep or steps. The templates offer more than 40 ideas, the Hall of achievements keeps what you finished, and each can be shared as an image made on this device.</p><p>These goal plans, areas, pictures, sub-goals and average goals are kept on this device and, with an account, <strong>travel in your encrypted sync</strong> (Settings → Sync, &ldquo;Also sync my extras&rdquo;). A photo stays on the device it was added on; your other devices show a calm picture that says the photo is kept on another device. Export everything includes them.</p></HelpQuestion>
      <HelpQuestion id="al-reward-goals" question="Where are Reward goals?"><p>{/* Session AL sweep 3 (TK-146): said under Goals too, not only under More pages */}Reward goals count your unclaimed staking rewards. They appear in <strong>+ Create a goal</strong> once ZIGoals knows you use ZIGChain: switch on Earn, Staking or another money and chain page in Settings &rarr; Your pages &amp; buttons. Savings goals, count goals and projects need none of that.</p></HelpQuestion>
      <HelpQuestion id="aa-forecast" question="How is &ldquo;At this pace&rdquo; worked out?"><p>From the goal&rsquo;s own recorded progress: ZIGoals draws a straight line through the steps you recorded (the last 180 days) and reads where it reaches the target, with a range from your slower and faster stretches. It needs at least 3 recorded steps over 14 days or more; below that it says &ldquo;Not enough history yet&rdquo;, and when progress has not moved forward it gives no date. Every date is an estimate from your pace so far, not a promise. Today can show these for every goal: choose <strong>Pace forecasts</strong> while arranging Today.</p></HelpQuestion>
      <HelpQuestion id="aa-calculator" question="How does the compound interest calculator work?"><p>Wealth &rarr; <strong>Compound interest calculator</strong>. Enter a starting amount, what you add (weekly, monthly or yearly, at the start or end of each period), a yearly return and the years; sliders move the return and the years. You can add a yearly increase to what you put in and an inflation rate to see today&rsquo;s value. The chart shows what you put in and the growth, year by year, with markers where it passes 10,000, 100,000 and 1,000,000; the comparison lines show 2 points more or less return and starting 5 years earlier. Amounts are in USD or EUR. Every result is an estimate: returns are not guaranteed. Save scenarios to compare later (kept on this device), or <strong>Turn this into a goal</strong> to fill in a value goal.</p></HelpQuestion>
      <HelpQuestion id="aa-search" question="How do I search ZIGoals?"><p>The search button in the sidebar (on a phone, at the top) or the <kbd>/</kbd> key when you are not typing. One box finds goals, habits, foods and recipes, assets, pages, settings, Help answers and templates, all on this device; arrow keys move, Enter opens, Escape closes. Your last 8 searches are kept on this device, and you can clear them. The last row asks ZIGi, when ZIGi is on. <kbd>&#8984;K</kbd> or <kbd>Ctrl K</kbd> opens the command menu instead (go to a page, add a task, or Ask ZIGi).</p></HelpQuestion>
      <HelpQuestion id="aa-review" question="What is the Life review, and what does &ldquo;On the same days&rdquo; show?"><p>The Life review (<Link className="text-link" href="/app/review">Life review</Link>, also from Today&rsquo;s Updates and summaries) looks at the last seven days or this month so far beside the period before: highlights, wins, streaks, the goals that moved, the plans behind them, sleep, steps, water and meals, and net worth in each currency, never converted. Anything not recorded says so and is never counted as zero. Choose one focus for the next week or month (kept on this device); the review shows it again next time. The weekly reflection is still there, unchanged.</p><p><strong>On the same days</strong> compares days from two parts of your life over the last 90 days, like the nights after days with a long walk against the others. A pairing shows only when each side has 14 days of your own records, and it says what happened together, never why: a pairing is not a cause. Nothing leaves this device.</p></HelpQuestion>
      <HelpQuestion id="aa-data" question="Where can I see what is stored, and where?"><p>Settings &rarr; <strong>Your data</strong>: each part of your records and where it lives (encrypted sync, this device only, or worked out each time and never stored), how much this device holds, what is never stored, your copies and what ZIGi can see. Looking changes nothing. Export everything is linked from there.</p></HelpQuestion>
      <HelpQuestion id="aa-home-screen" question="Can I add shortcuts to my Home Screen, or share to ZIGoals from another app?"><p>Once ZIGoals is installed on Android with Chrome, a long press on its icon offers Quick add, Log water, Check in a habit and Ask ZIGi, and the share sheet of other apps offers ZIGoals: what you share (a title, text or a link) waits on its own page until you choose to make it a goal, ask ZIGi or search for it. Nothing is saved or opened before you choose. Pictures and files cannot be shared to ZIGoals yet. Safari on iPhone and iPad offers neither the shortcuts nor the share sheet entry for web apps, so there you open ZIGoals and use Quick add.</p></HelpQuestion>
      {/* Session AL (done for L3: P-NB-03, NB-191, NB-214, NB-217, NB-229): Help names XP, its table and its daily caps. */}
      <HelpQuestion id="al-xp" question="Where does XP come from, and why does water stop adding it?"><p>With the game layer on, XP comes from records you already keep, by one table: a habit done for the day {XP_RULES.habitComplete} XP (part done {XP_RULES.habitPartial}), a goal milestone ticked or a goal reached {XP_RULES.goalMilestone}, a contribution to a goal {XP_RULES.contribution}, the weekly review {XP_RULES.review}, a meal logged {XP_RULES.diaryEntry} (up to {XP_RULES.diaryCapPerDay} a day), a glass of water {XP_RULES.water} (up to {XP_RULES.waterCapPerDay} a day), a weight, a night of sleep or a meditation {XP_RULES.weight}, an activity {XP_RULES.activity}, and an Earn Academy lesson passed once. The daily caps are why water, and meals after a few, add nothing more that day: a busy diary never outweighs a habit. XP is worked out from the records each time and never stored, so Undo, or unticking, takes back exactly what that record gave; no rule ever takes away anything else. The Checklist earns badges, never XP. The weekly review&rsquo;s quest shows on the day you chose for the review, in Settings &rarr; Your areas &rarr; Weekly review day; the review&rsquo;s XP counts whenever you finish it. Journey lists where this week&rsquo;s XP came from.</p></HelpQuestion>
      {/* Session AP (owner-approved Health features 1–7): each new piece, in plain words. */}
      <HelpQuestion id="ap-mood-tags" question="Can I tag what a day went with, and see what goes with my good days?"><p>Yes. After you choose how a day feels in Health &rarr; Diary, add up to eight short tags, such as &ldquo;walk&rdquo; or &ldquo;friends&rdquo;. Health &rarr; Insights then shows, for each tag on at least five days with a mood, on how many of those days your mood was Good or Great, beside the other days. It goes with, not a cause. Tags stay on this device with your Health records; ZIGi and NOVA do not read them.</p></HelpQuestion>
      <HelpQuestion id="ap-symptoms" question="Can I follow symptoms such as headaches or pollen?"><p>Yes: Health &rarr; Diary &rarr; Symptoms and factors. Name up to 40 things and give each a level per day, from None to Strong; a day you skip stays unanswered. Your Life review&rsquo;s &ldquo;On the same days&rdquo; sets the ones you answer most beside your mood and sleep, in counts and only with 14 days on each side: things that go together, not a cause. It stays on this device; ZIGi and NOVA do not read it. It is not medical advice.</p></HelpQuestion>
      <HelpQuestion id="ap-orbits" question="What are the orbits in Health → Activity?"><p>Each orbit follows a goal you set yourself: steps today against your daily step target, active minutes against your &ldquo;active minutes&rdquo; health goal, and workout days this week against a workout habit with an &ldquo;X times a week&rdquo; schedule. The planet moves along its orbit as you go, and the numbers are written beside it. They are worked out from your records each time; no calories are estimated.</p></HelpQuestion>
      <HelpQuestion id="ap-trends" question="How do the trends in Health → Activity work?"><p>For steps, sleep, weight and resting heart rate, ZIGoals compares your average over the last 90 days with the last 365, from days with a record only. A trend shows once both sides have enough days, and always says how many; an arrow and a word (Up, Down, About the same) give the direction, which describes your numbers without calling it good or bad.</p></HelpQuestion>
      <HelpQuestion id="ap-splits" question="Does ZIGoals show my pace and kilometre splits from a GPX or TCX run?"><p>Yes, for runs imported from now on: the pace and the time of each kilometre are worked out on this device from the file&rsquo;s points when you import it, and kept with the workout; the route itself is still not kept. Runs imported earlier keep their summary only. A file over 5 MB, one with a DOCTYPE or its own entities, or one that is not a GPX or TCX file is refused with the reason.</p></HelpQuestion>
      <HelpQuestion id="ap-copy-meal" question="Can I copy a meal to another day or meal?"><p>Yes: Health &rarr; Diary &rarr; Copy a meal to another day or meal. Choose the day and meal to copy from and the day (up to today) and meal to copy to. The entries come over exactly as logged, beside anything already there; remove one like any entry.</p></HelpQuestion>
      <HelpQuestion id="ap-food-days" question="Where can I see how many days I logged food this month?"><p>Health &rarr; Insights &rarr; Days you logged food: how many days of this month so far have at least one diary entry, with each day marked. It is counted from your diary each time; nothing is judged.</p></HelpQuestion>
      {/* Session AP (owner-approved, Wealth): six money answers, each from your own records. */}
      <HelpQuestion id="ap-money-month" question="How do I see my money month by month?"><p>Wealth &rarr; Spending &rarr; Your money over time. <strong>Month by month</strong> shows what you logged as received and spent, and the difference, for the last 12 months with a record, as bars and as a table. <strong>Categories over a year</strong> shows each spending category over 12 months, and <strong>Top payees</strong> this month&rsquo;s biggest payees (the note on each entry) beside last month. A month with nothing logged says &ldquo;No records&rdquo;; it is never counted as zero. Each currency is shown on its own and never converted.</p></HelpQuestion>
      <HelpQuestion id="ap-money-tags" question="Can I tag my money entries?"><p>Yes. Your money over time &rarr; <strong>Tags</strong>: choose Tags beside an entry and type up to five, separated by commas (for example &ldquo;holiday, work&rdquo;); each is at most 24 characters and saved in lower case. Pick a tag to see only its entries and its totals, spending and income apart and each currency on its own. Tags are kept on this device beside your money log, are in Export everything and leave with an entry you remove.</p></HelpQuestion>
      <HelpQuestion id="ap-ready-to-assign" question="What is &ldquo;Ready to assign&rdquo; on Budgets?"><p>What you logged as income in the month, minus what that month&rsquo;s budgets hold, in each currency. More in budgets than logged as income says so as it is. With no income logged it says &ldquo;nothing logged as income this month&rdquo; instead of a figure. What rolls over from earlier months is not taken again. From your records only; not advice.</p></HelpQuestion>
      <HelpQuestion id="ap-age-of-money" question="What is the age of money?"><p>How long, on average, money you logged as received waited before you spent it, over the last 90 days. Each amount you spent is matched to the oldest received money not yet spent (first in, first out); its age is the days between the two. It needs at least 30 days of records and some income in those 90 days; until then it says &ldquo;Not enough records yet&rdquo;. Spending no logged income covers is left out and named.</p></HelpQuestion>
      <HelpQuestion id="ap-spending-pace" question="What does &ldquo;Your usual pace&rdquo; compare?"><p>What you have spent this month so far beside what your earlier months show by the same day: &ldquo;By the 14th you usually have spent &hellip;; this month &hellip;&rdquo;. &ldquo;Usually&rdquo; is the middle figure of up to 12 earlier months with spending logged, and it needs at least three of them. It compares your records; it does not forecast the rest of the month.</p></HelpQuestion>
      <HelpQuestion id="ap-bill-price-change" question="Why does a bill say it went up or down?"><p>When a bill found in your spending was paid at a different amount the last time than the time before, Upcoming bills says so: &ldquo;went up by &euro;0.50 since Oct 2026&rdquo;, with both amounts. It reads only your money log; a bill you added by hand has no payments to compare.</p></HelpQuestion>
    </Section>

    <Section id="whats-new-alpha" updated="Nov 14, 2026" eyebrow="WHAT&rsquo;S NEW" title="New in this Alpha, in your own words">
      {/* Session AL (PR-034, AL-HELP-006): the section opened on an old release's eleven answers; it now starts with this
          version's, the same ones Today's What's new card links (components/for-you/whats-new-card.tsx), plus the Checklist. */}
      <p>New in this version; each opens its answer:</p>
      <ul className="help-whats-new-now">{THIS_VERSION.map(([id, label]) => <li key={id}><a className="text-link" href={`#help-${id}`}>{label}</a></li>)}</ul>
      {/* Session AP (friends Alpha, 14 Nov): this release's answers, each short; the features' own answers are in their sections. */}
      <HelpQuestion id="ap-new-first-five" question="What is &ldquo;Your first five&rdquo; on Today?"><p>After the first setup, Today offers five small steps: Today itself, a goal, a habit, a meal and some money. Each opens the usual form and ticks itself once you have added one. It leaves when all five are done, or when you choose &ldquo;Not now, hide this&rdquo;. Nothing in it is sent anywhere.</p></HelpQuestion>
      <HelpQuestion id="ap-new-day-rule" question="Can a day count as done before every dot is lit?"><p>Yes, if you choose: Settings &rarr; Your app &rarr; Checklist &rarr; &ldquo;A day counts as done at&rdquo;. At 4, a day with six dots counts once four are lit; a shorter day once all its dots are. Your streak flame and Journey&rsquo;s orbit badges follow it; a Perfect orbit still needs every dot in order. It applies from the day you choose it on: past days keep the rule they had, so nothing already counted changes. The default is every dot.</p></HelpQuestion>
      <HelpQuestion id="ap-new-bento" question="What is the Bento view?"><p>On a computer, Today (below its welcome header), Goals, Habits, Health and Wealth offer &ldquo;List&rdquo; or &ldquo;Bento&rdquo; beside the layout lock. Bento shows the same cards as tiles side by side. List stays the default, and your choice is remembered for each page on this device only.</p></HelpQuestion>
      <HelpQuestion id="ap-new-launchers" question="Why do the round buttons at the side slide away sometimes?"><p>On a computer, ZIGi, the Checklist, music and the Earn dock slide halfway into the edge while they would sit on top of what you are reading, and come back when nothing is under them. Point at them or reach them with the keyboard and they are back at once. With Motion Off or reduced motion they move without sliding. Tucking a button away yourself still works as before.</p></HelpQuestion>
      <HelpQuestion id="ap-new-settings" question="Why are Settings&rsquo; groups folded?"><p>So the page fits on one screen: on a computer or a tablet each group shows its name and one line of what it holds. Open the ones you use; they stay open on this device. A link to a setting (from Help, Search or a page) opens its group for you. On a phone, Settings keeps its own list.</p></HelpQuestion>
      <HelpQuestion id="ap-new-plan" question="What is new for planning my days?"><p>The Agenda&rsquo;s day can be shown by the hour, to place a task at a time; Tasks has This evening and Someday lists and a priority matrix; Today can count down the days to a date you choose; the Journal counts your words and writing days. Each has its own answer in Help.</p></HelpQuestion>
      <HelpQuestion id="ap-new-money" question="What is new for my money?"><p>Wealth &rarr; Spending shows your money month by month, each category over twelve months and where you spent most; entries can carry tags; Budgets says what is ready to assign this month and the age of your money; Spending compares this month with your usual pace; and a bill says when its amount changed. All of it is worked out from your own entries, never a forecast.</p></HelpQuestion>
      <HelpQuestion id="ap-new-health" question="What is new in Health?"><p>Mood check-ins can carry tags and Health can follow symptoms, each with what goes with your days in counts (never a cause); Activity shows orbits for your own goals and trends over 90 days and a year; a GPX or TCX run gets its pace and kilometre splits; and a meal can be copied to any day. These stay private like the rest of Health.</p></HelpQuestion>
      <HelpQuestion id="ap-new-feedback" question="What do the device details in Send feedback contain?"><p>Only what you see in the box before you send: the browser and system by name, the window and screen size, the theme, the motion settings, whether ZIGoals is installed, the time zone and the app version. No account, device or wallet id and none of your records. You can edit or delete any of it, or copy it with &ldquo;Copy these details&rdquo;.</p></HelpQuestion>
      <p>Before that, eleven small things arrived together. Each is optional and counts only your own entries.</p>
      <HelpQuestion id="auto-checkins" question="Can a habit tick itself off from my Health journal?"><p>Yes. Edit a habit you are building and, under &ldquo;From your Health journal&rdquo;, choose &ldquo;Done automatically when&rdquo;: water, steps, active minutes, a weight reading{SYNC_WRITES ? ', time asleep, in bed by a time, mindful minutes' : ''} or one of your exercise counters, with a target if you like. When you open Today, Habits or Health and the day&rsquo;s Health records reach it, the habit is ticked off once, and the card says so. Tapping the habit yourself always wins, and Undo keeps it off for that day. {SYNC_WRITES ? <>The rule and the marks it leaves are kept with your Health records, so with Health sync on another device won&rsquo;t tick the same day off again; the check-ins it makes are ordinary check-ins.</> : <>The rule stays on this device; the check-ins it makes are ordinary check-ins.</>}</p></HelpQuestion>
      <HelpQuestion id="health-goals" question="What is a health goal, and where does its progress come from?"><p>A health goal watches one thing you already record in Health: steps, water, an exercise counter, active minutes, or your weight trend. You choose the target and the window; ZIGoals only counts your own entries, and shows &ldquo;No data yet&rdquo; when there is nothing to count. It never suggests a target, never grades a result and gives no medical advice. {SYNC_WRITES ? 'Health goals are kept with your Health records, and sync only when you turn on Health sync.' : 'Health goals stay on this device for now.'}</p></HelpQuestion>
      <HelpQuestion id="skips" question="I&rsquo;m away for a week. Will my streak break?"><p>No. A skipped day is neutral: it neither adds to a streak nor breaks it. Plan a skip from a habit&rsquo;s &ldquo;History &amp; reflection&rdquo; for a single day, or mark a whole range with &ldquo;Vacation&rdquo; at the top of Habits. Reminders stay quiet on skipped days, and you can remove a planned skip at any time. Rest days need no marking at all: the days off your schedule never count against you.</p></HelpQuestion>
      <HelpQuestion id="weekly-review" question="What is the weekly review?"><p>On the day you choose in Settings, Today offers a short look back at your week: what went well, your goals, habits, health and wealth, and one intention for next week. Every step shows your own numbers for that week, and every field is optional. Finish it, or skip it with one tap; it never nags. {SYNC_WRITES ? 'Your review is kept with your Today settings and your words about health with your Health records: with encrypted sync on, the review syncs with your settings, and the health words only when Health sync is on.' : 'Your words stay on this device for now.'}</p></HelpQuestion>
      <HelpQuestion id="fasting" question="How does the fasting timer work, and is it right for me?"><p>It is a clock: choose 12:12, 14:10, 16:8 or your own target from 1 to 24 hours, start, and stop when you decide. It keeps your last fasts as hours and targets, nothing more: no streaks, no records, no calories, and it never compares one fast with another. A fast is stopped automatically at 24 hours. Fasting isn&rsquo;t for everyone: if you&rsquo;re pregnant, under 18, have a medical condition or an eating disorder, or take medication, talk to a doctor first, and stop if you feel unwell. ZIGoals gives no medical advice.</p></HelpQuestion>
      <HelpQuestion id="insights" question="What are the &ldquo;Something you might notice&rdquo; cards?"><p>When your journals hold at least two weeks of matching records, Today may show a simple pairing in them, in counts: for example, on how many of the days you walked more you also logged water, compared with the other days. The numbers are only your own entries, and the card shows exactly how it counted them. A pairing is not a cause and not advice. Dismiss a card and it stays away for four weeks.</p></HelpQuestion>
      <HelpQuestion id="imports" question="Can I import a CSV from another app?"><p>Yes, from any spreadsheet or export that has a header row: choose the file, match its columns, check the preview and confirm. Transactions go into a Portfolio, holdings into Wealth, meals into Health&rsquo;s diary. The file is read on this device and never uploaded; blank cells stay unknown rather than becoming zero; a coin that isn&rsquo;t recognised is yours to choose or skip. One tap undoes an import until you change any of the records it added. A MyFitnessPal or Cronometer file is recognised and its columns are matched for you to check. Whole exports from Apple Health, Samsung Health, Oura and Loop Habit Tracker come in from Settings → Switch to ZIGoals.</p></HelpQuestion>
      <HelpQuestion id="export-everything" question="Can I get all my data out?"><p>Yes, any time: Settings &rarr; &ldquo;Export everything&rdquo; makes one ZIP on your device with a JSON file of every record and a CSV per area that opens in a spreadsheet. An encrypted backup keeps a protected copy (and, with an account, so does sync); this file is your own readable one. It is readable, so keep it private. Settings &rarr; Your data &rarr; &ldquo;Restore from a backup&rdquo; reads it back: you see what it holds, choose per part to merge or replace, and can undo. If your account&rsquo;s cloud copy was deleted, this device keeps that account&rsquo;s records, locked in the app, and Export everything still copies them.</p></HelpQuestion>
      <HelpQuestion id="quick-add" question="What can I type into Quick add?"><p>A short English line about water, weight, steps, a run, walk, cycle or swim with its minutes, sleep, one of your exercise counters, or a habit by its name: &ldquo;drank 2 glasses of water&rdquo;, &ldquo;weight 78.4&rdquo;, &ldquo;walked 8,000 steps&rdquo;, &ldquo;ran 5k in 28 min&rdquo;, &ldquo;slept 7h&rdquo;, &ldquo;+2 pushups&rdquo;, &ldquo;meditated&rdquo;. ZIGoals shows what it will save before you tap Save, and tells you when it did not understand. Add &ldquo;yesterday&rdquo; to log for yesterday.</p></HelpQuestion>
      <HelpQuestion id="push-reminders" question="Can a reminder reach me when ZIGoals is closed?"><p>Yes, if you turn it on for a device: Settings &rarr; &ldquo;Reminders when closed&rdquo;. After a reminder time you set, your device shows one notification, &ldquo;A reminder from ZIGoals&rdquo;; if you turn on &ldquo;Show what a reminder is for in notifications&rdquo; there, it names the habit instead, written on this device and never sent to the server. Opening it brings you to Today. It needs a signed-in account, and on an iPhone it works only in the app saved to your Home Screen. The server gets your reminder times, your time zone and the weekdays, your quiet hours, and the address your browser hands out for push messages, never a habit&rsquo;s name, a count or anything you record. Turn it off any time: &ldquo;Turn off and delete from the server&rdquo; removes everything about that device at once. It is not available in every build; the panel says so.</p></HelpQuestion>
      <HelpQuestion id="guide" question="What is the Guide, and what does it read?"><p>The Guide is a short note on Today, at most one a day, made from your own records on this device: an open habit in the evening, a streak at a round number, a goal&rsquo;s next date, your weekly review when it is ready. It is off until you turn it on in Settings &rarr; &ldquo;Guide on this device&rdquo;, and every note is labelled &ldquo;Guide &middot; on this device, no AI service&rdquo;: fixed rules, no model, no service, nothing sent anywhere. It never gives money or medical advice and never moves anything. &ldquo;Not today&rdquo; hides a note; the switch in Settings turns the Guide off again.</p></HelpQuestion>
    </Section>

    {/* Session AK G2 (RELEASE_REVIEW R24): what changed in earlier releases, in one place after What's new, so the topics
        above stay task-shaped ("How do I…", "Is my data…"). Every answer keeps its id, so links, What's new and Search
        (lib/search/static.ts) still open it in place. */}
    <section className="help-earlier" id="earlier-updates" aria-labelledby="help-earlier-updates">
      <p className="eyebrow">EARLIER UPDATES</p>
      <h2 id="help-earlier-updates">Earlier updates</h2>
      <p className="help-earlier-lede">What changed, release by release, kept for reference. Each entry says how that release worked; some controls have moved since, and a few need an account or the money and chain pages switched on. For how to do something today, start with the topics above.</p>
      {/* Session AL Part 15 (GAP-178, C-DVG-90): the public release history, newest first (lib/help/release-history.ts). */}
      <Section id="release-history" updated="Nov 8, 2026" eyebrow="RELEASE HISTORY" title="Every published version, newest first">
        <p>Help opens for anyone, with no account, so this list is public. The version you are using is under <a className="text-link" href="#whats-new-alpha">What&rsquo;s new</a>.</p>
        <ol className="help-releases">{RELEASES.map(r => <li key={r.alpha}><strong>Alpha {r.alpha}</strong> <span className="fine">· {r.date}</span><br/>{r.title}{r.help && <> · <a className="text-link" href={releaseHref(r)}>Read more</a></>}</li>)}</ol>
      </Section>
      <Section id="earlier-changes" updated="Nov 1, 2026 or earlier" eyebrow="SMALLER CHANGES" title="Smaller changes, and where things moved">
        <HelpQuestion id="z-panel" question="What changed in ZIGi&rsquo;s panel?"><p>One row at the top: ZIGi, its name and a small line saying which AI answers (with your own AI connected, tap it to change the model), then New chat, Expand, Pop out on a computer, &ldquo;&#8943;&rdquo; and Close. &ldquo;&#8943;&rdquo; holds History, Customize, Settings, Meet ZIGi, Help and, when the music player shows, Music. A new chat is one greeting and the message box; the <strong>Suggestions</strong> chip by the box opens Ideas, Your day and Yours, your own suggestions. A card you added, declined or undid folds to one line, with Undo while it lasts, and an earlier reply&rsquo;s cards you left fold away once a newer reply brings cards. Under each reply, one row of buttons (copy, read aloud, try again, useful, not useful) and &ldquo;&#8943;&rdquo; for the rest: Copy as Markdown, Think deeper, Continue in my AI and the token count. Nothing in the panel wraps onto a second line, on a phone or a wide screen.</p></HelpQuestion>
        <HelpQuestion id="z-status" question="Where are the Alpha notices and the wallet buttons now?"><p>Every page starts with its own header. The Alpha&rsquo;s facts are one compact notice at the top the first time (close it with &times;; it stays closed on this device), and always in Settings (its &ldquo;About this alpha&rdquo; panel and Settings &rarr; Your data) and in &ldquo;About this Alpha&rdquo; below: nothing moves unless you sign it, staking and votes signed only in your own wallet after a review screen (nothing else moves, and ZIGoals never holds keys), contract execution disabled, records in this browser that are not a backup. On a phone, More &rarr; <strong>Status &amp; wallet</strong> opens the Status sheet: the network and what it means, On this device and Connect Keplr (once you choose a wallet or a money tool), the mode, storage and sync, in the Showcase its own line, and More wallets. On a computer the wallet buttons sit in the row under the notice.</p></HelpQuestion>
        <HelpQuestion id="z-more" question="What else changed in this release?"><p>Today is one centred column when nothing sits beside it. Until you connect Keplr, the words say what you have: &ldquo;Practice money (no real value)&rdquo;, &ldquo;On this device&rdquo;. Asset amounts read grouped in your language, like 300,000 ZIG; you still type them without separators. On a phone, a goal&rsquo;s card shows its name, ring and next step, and the rest is on the goal&rsquo;s page; ZIGi is the one floating button, and Music sits in ZIGi&rsquo;s &ldquo;&#8943;&rdquo; and in More. &ldquo;Ask ZIGi about this habit&rdquo; is in each habit&rsquo;s menu, and &ldquo;Ask ZIGi about my habits&rdquo; at the top of Habits. Help comes last in the menu, and &ldquo;Send feedback&rdquo; at the foot of the page opens the <a className="text-link" href="#feedback">feedback form</a>.</p></HelpQuestion>
        <HelpQuestion id="aa-more" question="What else is new: cards on Today, more Undo, an Offline sign?"><p>Today can show life balance, pace forecasts, the calculator and the Life review as cards you choose while arranging Today, kept on this device. Undo now follows removing a favourite, archiving an asset or an account, removing an account or a milestone, a calculator scenario and a Life review focus. While the browser is offline a small &ldquo;Offline&rdquo; pill sits in the header, and parts that load on demand say so instead of failing. Small text is larger and easier to read across the app.</p></HelpQuestion>
      </Section>
      {/* Session W Part 24: this release's features, each answer linkable from What's new and the feature itself. */}
      <Section id="whole-life" updated="Nov 4, 2026" eyebrow="YOUR WHOLE LIFE" title="Sleep, mind, music, chess, links and more">
        <p>This release adds sleep, meditation, focus sounds, chess, your own links and a music player, ways to bring your data from other apps, and more control over what shows. Everything is optional, works on this device first, and keeps your numbers honest.</p>
        <HelpQuestion id="w-pages" question="Can I hide pages and buttons I don&rsquo;t use?"><p>Yes: Settings &rarr; <Link className="text-link" href="/app/settings#your-pages">Your pages &amp; buttons</Link> has a switch for every page and button (Settings and Help always show), the page ZIGoals opens on, and &ldquo;Show everything again&rdquo;. A hidden page keeps its records and still opens from a link, with a note to show it again. With sync on, the choices travel with your settings.</p></HelpQuestion>
        <HelpQuestion id="w-welcome" question="Can I see the welcome again?"><p>Yes: <Link className="text-link" href="/app/welcome">Show the welcome</Link>. Picking what you want to improve sets your pages and Today; nothing is saved before &ldquo;Finish setup&rdquo;, and running it again adds nothing twice.</p></HelpQuestion>
        <HelpQuestion id="w-sleep" question="How does Sleep work, and what is sleep debt?"><p>Health &rarr; Sleep: log a night or a nap, or tap &ldquo;I&rsquo;m going to bed&rdquo; and &ldquo;I woke up&rdquo;; add quality, tags and a note. Sleep debt is, for each logged night of the last 7 days, your goal minus the time you slept, added up; bedtime consistency is how much your bedtimes vary over the last 14 nights (at least 4). Time asleep says &ldquo;estimated&rdquo; until you add how long it took to fall asleep and how long you were awake in the night. This is not medical advice: if poor sleep goes on, talk to a doctor.</p></HelpQuestion>
        <HelpQuestion id="w-meditation" question="What does Meditation keep?"><p>The sessions you time or breathe through, your mood before and after if you note it, a note, minutes you did elsewhere, and a weekly goal if you set one, in your Health journal like the rest of Health. The breathing circle moves only while the page is visible and motion is allowed; otherwise words and a count guide you.</p></HelpQuestion>
        <HelpQuestion id="w-sounds" question="Where do the focus sounds come from?"><p>In Health &rarr; Meditation, or in the music player once you show it. They are made in your browser: no file is downloaded and nothing is requested. A timer up to 90 minutes fades them out; &ldquo;Stop when I leave ZIGoals&rdquo; stops them when you switch away; a reload stops them too.</p></HelpQuestion>
        <HelpQuestion id="w-import" question="Can I bring my data from Apple Health or other apps?"><p>Yes: Settings &rarr; <Link className="text-link" href="/app/settings#switch-import">Switch to ZIGoals</Link> reads Apple Health&rsquo;s export.zip, Samsung Health, Oura (CSV) and Loop Habit Tracker on this device, nothing uploaded. A preview shows what fits, Health&rsquo;s box starts unticked, and each import can be undone. Garmin and Streaks are recognised but not read yet, and say why.</p><p>Fitbit: its old connection ended on 30 October 2026, so ZIGoals no longer imports from Fitbit. Anything you brought in before stays in your Health journal, readable and in Export everything.</p></HelpQuestion>
        <HelpQuestion id="w-devices" question="Can I connect my watch, ring or scale?"><p>In Health, open Devices from the link at the end of the page (<a className="text-link" href="/app/health?view=devices">Health &rarr; Devices</a>{/* eslint-disable-line @next/next/no-html-link-for-pages -- a full load: Health's Bluetooth policy applies to its own document */}): a Bluetooth heart-rate monitor or scale works in Chrome or Edge on a computer or an Android phone (not on iPhone: Safari has no Web Bluetooth). Oura, Withings, Polar and Strava are built but need ZIGoals to register with each service first, so they say &ldquo;Needs setup by ZIGoals&rdquo;. Apple Health has no web connection: import its export (above). Health Connect on Android has none either, and no export ZIGoals reads: import from the app that writes to it, such as Samsung Health or Google Health.</p></HelpQuestion>
        <HelpQuestion id="w-quick" question="What are the quick buttons in the diary?"><p>&ldquo;Copy yesterday&rsquo;s&rdquo; breakfast, lunch, dinner or snacks, &ldquo;Repeat yesterday&rdquo;, your pinned and usual items as one-tap chips, and your own water sizes. Each copies exactly what you logged.</p></HelpQuestion>
        <HelpQuestion id="w-habits" question="What are challenges and stacks?"><p>A challenge is a habit with its own end date, 30 days or your choice from 7 to 365, with one calm note when it ends; rest days are neutral. A stack shows habits you do one after another together, with an optional reminder on this device.</p></HelpQuestion>
        <HelpQuestion id="w-goals" question="What do milestones and &ldquo;On track?&rdquo; show?"><p>Milestones with a value and a date, marked on the goal&rsquo;s bar. &ldquo;On track?&rdquo; works with zero return and your own numbers: what is left, the date it points to, and what it needs per week or month. A &ldquo;what if it grew&rdquo; figure is your own assumption and is never stored.</p></HelpQuestion>
        <HelpQuestion id="w-wealth" question="Where do my accounts and debts live?"><p>On this device, and with an account they also travel in your encrypted sync (inside your Goals &amp; Wealth records), so your other devices show them too. Net worth is shown per currency, never converted; holdings with a known value count as their own line, and an unknown value is never counted as zero. A payoff date appears only from your own rate and payments. Nothing links to a bank, and nothing moves money.</p></HelpQuestion>
        <HelpQuestion id="w-wrapup" question="What is the evening wrap-up?"><p>A card on Today, off until you turn it on in Settings &rarr; <Link className="text-link" href="/app/settings#wrap-up">Evening wrap-up</Link>: from the time you choose (18:00 unless you change it) it lets you tick off the day, write tomorrow&rsquo;s intention and, if you like, note a mood (kept in Health).</p></HelpQuestion>
        <HelpQuestion id="w-chess" question="What does Chess send to chess.com and Lichess?"><p>Only the usernames you enter, each to its own site, from your browser, one request at a time, for public data. Puzzles and TV load only when you tap them, and &ldquo;Play&rdquo; opens the site. Chess is hidden until you show it under Your pages &amp; buttons.</p></HelpQuestion>
        <HelpQuestion id="w-portfolio" question="Where do Portfolio&rsquo;s charts and changes come from?"><p>From your own transactions and CoinGecko&rsquo;s dated prices; a gap is never guessed. The 1-hour and 7-day changes and the market figures need the updated market service and say &ldquo;Not provided&rdquo; until it runs.</p></HelpQuestion>
        <HelpQuestion id="w-links" question="What can I put in My links?"><p>Your socials, apps and sites as https links, with your own name and a plain icon (never a network&rsquo;s logo). Each opens in a new tab without a referrer; ZIGoals adds nothing to the address and fetches nothing from it.</p></HelpQuestion>
        <HelpQuestion id="w-music" question="Can ZIGoals play my Spotify or Apple Music?"><p>The focus sounds always play. Spotify works once this site&rsquo;s owner has registered it, with Spotify Premium: ZIGoals controls Spotify&rsquo;s own apps and speakers and plays nothing in the page, and for now only up to five invited accounts can connect. The Spotify sign-in stays sealed on this device. Apple Music opens in its own app; playing it inside ZIGoals needs an Apple Developer membership. The music player is hidden until you show it.</p></HelpQuestion>
        <HelpQuestion id="w-signout" question="How do I sign out all my other devices?"><p>With an account (where accounts are switched on), signed in: Settings &rarr; <Link className="text-link" href="/app/settings#encrypted-sync">Account &amp; devices</Link> (Account &amp; sync on a phone) &rarr; Devices and sessions &rarr; &ldquo;Sign out all other devices&rdquo;: every other device stops syncing at once and is signed out at the email provider; this one stays signed in. What they already downloaded stays on them, so after losing a device also rotate the vault key. You confirm with your recovery secret, on a remembered device too.</p></HelpQuestion>
        <HelpQuestion id="z-step-up" question="Why does ZIGoals ask for my recovery secret again?"><p>Deleting cloud records (all of them, or one section), deleting your account, signing other devices out and rotating the vault key ask for your recovery secret every time, on every device, a remembered one included. It is checked on your device first; then a proof made from it goes with the request, and the sync service checks it, so a device someone else picks up, or a stolen session, can&rsquo;t end your data or your access. A device you ask to remember opens without the secret for 30 days, then asks for it once.</p></HelpQuestion>
        <HelpQuestion id="w-newer-section" question="What does &ldquo;saved by a newer ZIGoals&rdquo; mean?"><p>Using sleep, meditation, your pages or links raises the format of that part of your data (Health, or Today&rsquo;s settings). An older ZIGoals, on a device not yet updated or opening a copy made here, can&rsquo;t read that part: it says so, keeps it as it is and changes nothing. Update that device and everything is read again; nothing is lost.</p></HelpQuestion>
        <HelpQuestion id="w-web-limits" question="What can&rsquo;t a web app do?"><p>It can&rsquo;t sync in the background, and it can&rsquo;t remind you while it is closed unless you turn on &ldquo;Reminders when closed&rdquo;; Bluetooth works only in Chrome and Edge (not on iPhone); on an installed iPhone app, connect services from Safari, because their sign-in pages open outside the app; and Apple Health has no web access at all, so use its export.</p></HelpQuestion>
      </Section>

      <Section id="aa" updated="Nov 1, 2026 or earlier" eyebrow="HABITS, HEALTH AND THE GAME LAYER" title="Deeper Habits and Health, and ZIGi knows every bit of it">
        <HelpQuestion id="aa-habits" question="How do the time-of-day sections, the timer&rsquo;s Finish, days since, skips, notes and routines work?"><p>Each habit has a time of day in its editor (morning, afternoon, evening, any time). The Habits page and Today&rsquo;s habits group them; the section the clock is in opens first, and a fold you choose is remembered on this device. The timer&rsquo;s <em>Log reviewed duration</em> (its finish) stops it and logs today&rsquo;s check-in with the minutes it measured, in one tap; it survives a reload, and an optional end bell plays outside your quiet hours. A quit habit counts the days since the last slip, keeps your longest run, shows the slips on a calendar and, if you enter what the habit cost per day, an estimate of the money kept: your own figure times days, nothing else. &ldquo;Skip today&rdquo; takes a reason; a check-in can carry a note and a mood, both shown in the history. A routine is a chain of habits played one after the other, with the timer where a habit has minutes; four templates (morning, evening, workout, focus) create the habits for you. The year view shows every day of the year per habit and for all habits together.</p></HelpQuestion>
        <HelpQuestion id="aa-journey" question="What is the game layer, and is it on?"><p>Off for everyone until you turn it on under Settings &rarr; Your app &rarr; Game layer (the Showcase has it on). XP comes only from real actions in your journals and is never stored, so Undo takes it back. Levels have names, three daily quests come from the pages you show, weekly challenges compare you with your own last week, badges keep only the day you first earned them, and a streak freeze is earned, never bought. Nothing is ever taken away and nothing nags. The Journey page (/app/journey) shows the level ring, XP this week, the quests, the badge cabinet and the path ahead.</p></HelpQuestion>
        <HelpQuestion id="aa-health" question="What are the weight trend, the energy estimate, the coach, micronutrients, the planner and recipe import?"><p>The trend smooths your readings (an exponential moving average) and shows the weekly rate and your goal line. The energy estimate compares a month of logged intake with the trend&rsquo;s change; it needs at least fourteen logged days and six readings, shows a band, and is an estimate, not medical advice. Once a week the coach sums the week up in one sentence and asks: keep the calorie target or adjust it; &ldquo;adjust&rdquo; writes the target through the form you already use, and your answer stays on this device. Micronutrient targets cover the seven nutrients the journal has (fiber, sugar, saturated fat, sodium, potassium, calcium, iron); unknown stays unknown, never zero. The macro view can show net carbs, a keto split or your own split; it changes nothing in your records. The planner puts a recipe or a food into a day and meal; the grocery list groups what you need by aisle, ticks off what you bought, and one tap logs the planned meal when you eat it. To import a recipe, paste its text and confirm the lines, or paste a web address: the app reads the recipe the page publishes for search engines (name, ingredients, yield; https pages only, never private addresses) and imported ingredients become foods with unknown nutrition until you fill them in. The fasting timeline shows the hours of a fast with neutral marks at 12, 16, 18 and 24 hours and makes no health claims. Measurements have a chart per kind and your own kinds; progress photos stay on this device (they never sync, they are in Export everything and erased with the account). The sleep score shows its formula; the water ring uses your own sizes.</p></HelpQuestion>
        <HelpQuestion id="aa-swipes" question="Why does a swipe not delete?"><p>On a phone a swipe right completes a habit, a swipe left only reveals Edit, Skip and Archive; delete always opens the confirmation and offers Undo. A fast flick never deletes anything. Diary entries swipe the same way.</p></HelpQuestion>
        <HelpQuestion id="aa-welcome" question="What does the new welcome set up, and can I undo it?"><p>You pick what matters and two or three focuses; the welcome creates matching habits, goals and Today widgets. For a day, &ldquo;Undo setup&rdquo; on the welcome card removes exactly what it created, and only that.</p></HelpQuestion>
        <HelpQuestion id="aa-reminders" question="Where are my reminders?"><p>Settings &rarr; Reminders (the link under &ldquo;Reminders when closed&rdquo;): habit and water reminders, bedtime, the weekly review, a fast&rsquo;s end, a goal check-in, and quiet hours. Reminders show on Today; while ZIGoals is closed they reach a device only after you turn on Settings &rarr; Reminders when closed there, which needs a signed-in account.</p></HelpQuestion>
        <HelpQuestion id="aa-zigi" question="What can ZIGi do with all this?"><p>Every new action as a card: move a habit to the morning, start or finish a timer, start a routine, set a habit&rsquo;s area or a quit habit&rsquo;s cost, use a streak freeze, set a micronutrient target or the macro view, answer the coach, import a pasted recipe, turn the game layer on or off, and open the Journey, the year view, routines, the planner, insights, import and reminders, in English and Dutch, typed or spoken. A recipe web address, money, weight, fasting and deletions never auto-accept.</p></HelpQuestion>
      </Section>
      {/* Session AB-Cloud (ADR-023): this release's own topic, before the earlier ones (mirrored in lib/search/static.ts). */}
      <Section id="ab" updated="Nov 1, 2026 or earlier" eyebrow="SYNC, RESTORE AND POINT &amp; TELL" title="Everything travels with you, and nothing is lost">
        <HelpQuestion id="ab-sync" question="What syncs now?"><p>With an account and encrypted sync on: Goals and Wealth (now with your accounts, debts and milestone dates), Habits and Today&rsquo;s preferences, and Health only after you tick it on each device. Your extras travel too, encrypted on this device before they leave it: goal plans and life areas, sub-goals, stories and card art, average goals, calculator scenarios, the Life review focus, Today&rsquo;s cards, the reminders plan, habit extras, routines and the game. Health&rsquo;s extras (the coach&rsquo;s answers, micronutrient and vitamin targets, how macros are shown, aisles, custom measurements and vitamins) travel only while Health sync is on. Settings &rarr; Account &amp; devices &rarr; &ldquo;Also sync my extras&rdquo; turns them off on a device, and &ldquo;Remove the extras from the cloud&rdquo; deletes their encrypted copy (every device keeps its own). Photos, recent searches, the welcome&rsquo;s setup, display choices, Point &amp; tell notes and ZIGi&rsquo;s chats and settings stay on each device.</p></HelpQuestion>
        <HelpQuestion id="ab-photos" question="Do my photos sync?"><p>No, on purpose: vision-board and progress photos stay on the device where you added them. Another device shows the goal&rsquo;s colours instead of the photo. &ldquo;Export everything&rdquo; includes your photos, and &ldquo;Restore from a backup&rdquo; brings them back to a device.</p></HelpQuestion>
        <HelpQuestion id="ab-restore" question="How do I restore from a backup?"><p>Settings &rarr; Your data &rarr; <strong>Restore from a backup</strong>, then choose a ZIP made by &ldquo;Export everything&rdquo;. You see each part it holds beside what this device holds now, and nothing changes until you confirm. Per part: leave it, <strong>merge</strong> (adds only what the backup has and this device doesn&rsquo;t; nothing here is changed) or <strong>replace</strong> it. &ldquo;Undo this restore&rdquo; puts everything back, and leaves alone anything that changed since; it now also works after a reload, on this device for 7 days, until you use it or choose &ldquo;Keep the restore&rdquo;. Keys and secrets are never in the file; restoring Health never turns Health sync on.</p></HelpQuestion>
        <HelpQuestion id="ab-point-tell" question="What is Point &amp; tell?"><p>A way to tell us exactly what you mean. Settings &rarr; Help &amp; diagnostics &rarr; &ldquo;Show the Point &amp; tell button&rdquo;. Press the pin button, then tap the part of the page you mean (with a keyboard, Tab to it and press Enter); the tap opens a note instead of the page. Your notes are numbered and stay on this device until you copy, download or email them. Esc always cancels.</p></HelpQuestion>
        <HelpQuestion id="ab-vitamins" question="Can I track vitamins?"><p>Yes: A, C, D, E, K, B12 and folate. Health &rarr; Foods &amp; recipes &rarr; edit a food &rarr; &ldquo;Vitamins (optional)&rdquo;, as the label gives them per serving. Health &rarr; Targets lists them after the seven nutrients, with targets you can edit (common adult reference values by default, not advice). A vitamin you didn&rsquo;t enter stays unknown, never zero, and a recipe shows a vitamin only when every ingredient gives it.</p></HelpQuestion>
        <HelpQuestion id="ab-amounts" question="Can I type 3,250.50 or 3.250,50?"><p>Yes, wherever you type an amount, when it can be read only one way; a Goal&rsquo;s preview shows the plain value before you save. &ldquo;1,234&rdquo; could mean 1234 or 1.234, so ZIGoals asks you to type it without the separator; on a device whose language groups thousands with a dot, &ldquo;1.234&rdquo; is asked about the same way.</p></HelpQuestion>
        <HelpQuestion id="ab-currency" question="Why does a new goal start in euros (or dollars)?"><p>A new value Goal and a new Portfolio start in euros when your device&rsquo;s region uses the euro, and in US dollars otherwise. Change it any time; a currency you chose is always kept.</p></HelpQuestion>
      </Section>
      <Section id="abd" updated="Nov 1, 2026 or earlier" eyebrow="ONE LOOK FOR EVERY PAGE" title="Goals, Habits &amp; Health = Wealth, in one calm look">
        <HelpQuestion id="abd-look" question="What changed in how ZIGoals looks?"><p>Every page now shares one look: a crisp night sky, one header on Goals, Habits, Health, Wealth and the Journey with each pillar&rsquo;s own colour, one card style, one way to show an empty card, loading shimmer instead of &ldquo;Opening&hellip;&rdquo; lines, and one chart style with readable labels on a phone. Today opens with a Life overview: four rings, one per pillar, each showing only what your records say. Nothing you saved changed, and a saved page layout stays as you left it.</p></HelpQuestion>
        <HelpQuestion id="abd-footer" question="What is the banner at the bottom of every page?"><p>The footer: the ZIGoals wordmark, &ldquo;Goals, Habits &amp; Health = Wealth&rdquo;, the three steps on a glowing path, and the links to Help, feedback and your data; the page ends there (since Session AC the Alpha&rsquo;s facts are in Settings and in &ldquo;About this Alpha&rdquo;). The first time you see it in a visit its path draws itself; with reduced motion or Motion Off it simply shows at rest.</p></HelpQuestion>
        <HelpQuestion id="abd-showcase" question="Where did the warning banners go?"><p>The facts are all still there, in fewer places: one short Alpha notice at the top (dismiss it once), a small &ldquo;Showcase&rdquo; chip while the Showcase is on (tap it for what the Showcase is, Load again and Exit), Settings &rarr; Your data and Settings&rsquo; &ldquo;About this alpha&rdquo; panel, and Help&rsquo;s &ldquo;About this Alpha&rdquo;. Inside a card, fictional Showcase records carry a small &ldquo;Showcase&rdquo; tag.</p></HelpQuestion>
        <HelpQuestion id="abd-dock" question="Can I tuck ZIGi and the music button away?"><p>Yes. Both float at the right edge and fold away with their small arrows; they never move a card. On a phone, the music player also opens from More.</p></HelpQuestion>
        <HelpQuestion id="abd-gamify" question="What does the rocket do?"><p>It turns the game layer on or off and opens your Journey. With it on, &ldquo;Add widget&rdquo; on Today offers &ldquo;Level &amp; XP&rdquo; and &ldquo;Today&rsquo;s quests&rdquo;, kept on this device, and each page ends with a small Journey card showing that page&rsquo;s quest. Off, none of it shows; your streaks stay.</p></HelpQuestion>
        <HelpQuestion id="abd-goals" question="What is new on Goals?"><p>Cards show the name, status, amount, ring and what remains first; the sources and plan wait behind Details. &ldquo;Change artwork&rdquo; in a card&rsquo;s &#8943; menu picks one of fifteen scenes, with Undo, and it travels with your encrypted extras. The vision board is a mood board you can open full screen, and the tree grows your goals and sub-goals from one root.</p></HelpQuestion>
        <HelpQuestion id="abd-habits-health" question="What is new on Habits and Health?"><p>Habits: each time of day sits under its own sky, a routine plays full screen with ZIGi&rsquo;s plain hints, and a habit card opens its details only when you ask. Health: three highlight tiles at the top (weight trend, energy estimate, your coach), the meal planner swipes day by day on a phone, the grocery list is one tidy row per item, and micronutrients and vitamins read as rows with today&rsquo;s value.</p></HelpQuestion>
        <HelpQuestion id="abd-wealth" question="Which currency does Wealth show first?"><p>The headline is in your base currency: the one you pick under &ldquo;Totals in USD / EUR&rdquo; in Wealth&rsquo;s summary, or until then your device&rsquo;s default (euros in the euro area, US dollars otherwise). Amounts in the other currency stay in their own chip, never converted.</p></HelpQuestion>
        {/* Session AH (CO12, T-051, T-018): the data-freshness policy, as the code applies it (lib/market-quotes.ts QUOTE_FRESH_MS, lib/market-assets.ts CATALOG_FRESH_MS, lib/earn/client.ts EARN_FAMILIES). */}
        <HelpQuestion id="ah-freshness" question="How fresh are the numbers?"><p>Every live number says where it came from and when it was read. A market price counts as current for 15 minutes after it was observed; after that it is shown as an earlier price with its time, never as today&rsquo;s. The list of markets you can search is refreshed once a day. On Earn, figures read from ZIGChain and its apps are read again every 2 minutes while the page is open, and DefiLlama&rsquo;s third-party figures every 10 minutes; a hidden tab reads nothing. The Showcase uses one fixed set of example prices, labelled as a snapshot, so its numbers never drift. Your own records (balances, holdings you value yourself, goals and logs) change only when you change them.</p></HelpQuestion>
        <HelpQuestion id="abd-search-review" question="What changed in Search and the Life review?"><p>Search opens with the four pillars as shortcuts, marks each result with its pillar and, on a wide screen, previews the highlighted result. The Life review reads like a small magazine: a cover with your highlights, then one chapter per pillar; &ldquo;Share as an image&rdquo; still makes the picture on this device.</p></HelpQuestion>
      </Section>
      {/* Session AC (ADR-025): this release's visible changes, each linkable from What's new. */}
      <Section id="ac" updated="Nov 5, 2026" eyebrow="CALMER PAGES" title="Each thing once, and a calmer page">
        <HelpQuestion id="ac-habits" question="Why do my habit cards show their last 28 days?"><p>Each habit card now shows its last 28 days as two rows of coloured days right under the counter, so you see your rhythm without opening Details. Everything else (the timer, notes, trends, the challenge, history) still waits behind Details. Cards side by side keep one height, with &minus;, + and Done on one line.</p></HelpQuestion>
        <HelpQuestion id="ac-sky" question="Why is the top of each page plainer now?"><p>The night sky is the same picture, now with depth along the page: the top, behind the page&rsquo;s title, is plainer; the stars come in as you scroll towards the middle, where they are richest, and fade out again towards the end. Nothing moves: it follows where you are on the page, the same with reduced motion or Motion Off.</p></HelpQuestion>
        <HelpQuestion id="ac-footer" question="Where did the Alpha&rsquo;s facts below the footer go?"><p>Every page now ends with the footer banner (its link columns have since gone; every link is still in Help, Settings and the menu). The facts are all still there: in the notice at the top on your first visit, always in Settings &rarr; Your data and Settings&rsquo; &ldquo;About this alpha&rdquo; panel (with your mode and where your records live), and in Help&rsquo;s &ldquo;About this Alpha&rdquo;. Money and wallet actions keep their own labels where they happen.</p></HelpQuestion>
        <HelpQuestion id="ac-today" question="Why does Today show fewer cards?"><p>Today shows each thing once. {/* Session AL (B-109, B-202; COPY_AUDIT, deliberate): the Showcase shows one card named Daily Habits (the habits widget), so the answer says that card is the one that stays. */}On a new device, in the Showcase and on any Today you never arranged, today&rsquo;s habits show in one card named Daily Habits, your habits widget, and the second, built-in copy of that list stands aside; &ldquo;Your next goal action&rdquo; stands aside while the &ldquo;Next step&rdquo; tile already shows the same goal. Daily Health stays: it shows your macros, weight and steps beside the calories. Nothing is gone: unlock the layout and choose &ldquo;Show card&rdquo; to bring any of them back. A Today you arranged keeps your own choices.</p></HelpQuestion>
        <HelpQuestion id="ac-wealth" question="Where are &ldquo;Your assets&rdquo; and my accounts in Wealth?"><p>In one list, &ldquo;What you have&rdquo;, with one row of chips: All, Accounts, Debts, Assets, each asset class and Needs attention. Every asset card and every account or debt row is the same as before, with all its actions, and your net worth per currency sits with them.</p></HelpQuestion>
        <HelpQuestion id="ac-water" question="Where is the water ring in Health?"><p>In the Water card itself: one card with the ring, your target, one-tap buttons in your own sizes (each with Undo for a few seconds), a typed amount with its date, and today&rsquo;s entries to edit or remove.</p></HelpQuestion>
        <HelpQuestion id="ac-vision" question="Can I put my own picture on the vision board?"><p>Yes: on a tile, open &#8943; and choose &ldquo;Change image&rdquo;. The picture fills the tile at the same size and is kept on this device only, like every vision photo (it never syncs; Export everything includes it). &ldquo;Back to the default picture&rdquo; undoes it. In the Showcase the picture shows in this tab only, because the Showcase keeps no photos; &ldquo;Back to the illustration&rdquo; returns the drawing.</p></HelpQuestion>
        <HelpQuestion id="ac-more" question="What else is new in this update?"><p>Every page&rsquo;s tab names the Alpha (&ldquo;Reminders &middot; ZIGoals Alpha&rdquo;); a contribution to a custom asset reads &ldquo;1 unit &middot; a custom asset not in Wealth&rdquo; instead of a code; the reminders&rsquo; habit rows line up with the others; &ldquo;Your week&rdquo; counts a weight as a Health entry; ZIGi&rsquo;s chat keeps your place when you expand it or pop it out; the &ldquo;Make Today yours&rdquo; choices say which one is chosen; and Known limitations names a few more things the Alpha can&rsquo;t do yet.</p></HelpQuestion>
      </Section>
      {/* Session AD (ADR-026): this release's visible changes, each linkable from What's new. */}
      <Section id="ad" updated="Nov 4, 2026" eyebrow="LIGHT, NEBULA AND DARK" title="The final look, and three ways to see it">
        <HelpQuestion id="ad-themes" question="What are Light, Nebula and Dark?"><p>Three looks for ZIGoals, in the theme bar: at the bottom of the sidebar, first in Settings, under Appearance (on a phone, the Settings row &ldquo;Theme, motion &amp; display&rdquo;) and in the phone&rsquo;s More sheet. <strong>Nebula</strong> is ZIGoals&rsquo; own night-sky look and the default for everyone; its button shows a small ZG mark. <strong>Light</strong> is Nebula by day: a white page with a light colour mist and dark words, and every colour, chip, chart, ring and glow exactly as in Nebula; Today&rsquo;s welcome scene keeps its own soft night, the page ends in a dusk that turns to night at the footer banner, and the sidebar has its own light sky. <strong>Dark</strong> is a true dark look: flat near-black surfaces with no stars or mist, and Nebula&rsquo;s same colours and contrast. Switching is a short cross-fade (none with reduced motion or Motion Off). Your choice is a display setting of this device, like Motion Off: it stays here, is never synced, and a restore from a backup leaves it as it is. It is put on the page before the page shows, so you never see the wrong look first.</p></HelpQuestion>
        <HelpQuestion id="ad-banner" question="What changed in the footer banner, and where did its links go?"><p>The banner at the foot of every page is final: the new ZIGoals wordmark, &ldquo;Goals &middot; Habits &middot; Health&rdquo; and, larger, &ldquo;= Wealth&rdquo;, the three steps, and the whole planet behind them. The first time you see it in a visit, each word arrives with its step and the wordmark shines once; with reduced motion or Motion Off it simply shows its resting state. Its link columns are gone, and every link is still close: the pages are in the sidebar (on a phone, the tab bar and More); &ldquo;What&rsquo;s new&rdquo; and &ldquo;Send feedback&rdquo; are topics at the top of this page, and the &ldquo;Private security contact&rdquo; is in <a className="text-link" href="#feedback">Send feedback</a>; making a backup, storage and sync, and Your data are in <Link className="text-link" href="/app/settings">Settings</Link>. The social links and Back to top stay in the banner.</p></HelpQuestion>
        <HelpQuestion id="ad-hero" question="Why do Today&rsquo;s planets reach past the hero card?"><p>The planets now flow softly past the edges of Today&rsquo;s hero into the page, behind everything else: the same picture, carried on and fading out. Nothing moves and nothing covers what you read or tap. When you fold the hero, none of it shows.</p></HelpQuestion>
        <HelpQuestion id="ad-dates" question="Why do dates look the same everywhere now?"><p>Every page writes dates one way: &ldquo;17 Oct 2026&rdquo; or &ldquo;Oct 17, 2026&rdquo;, depending on your device&rsquo;s region, and times in your own clock, 14:05 or 2:05 PM. Some places say Today, Yesterday or Tomorrow instead. Only what you see changed: exports and your records keep their exact dates.</p></HelpQuestion>
        <HelpQuestion id="ad-sync-status" question="How can I see what has synced?"><p>Settings &rarr; Account &amp; devices, while your account is open, now shows <strong>Sync by section</strong>: Goals &amp; Wealth, Habits, Health (while Health sync is on), Today{SYNC_WRITES ? ', your extras and your Portfolio' : ''}. Each row says when it last synced in this session, how many changes are waiting, that you are offline and it will sync when you&rsquo;re back, or that it couldn&rsquo;t sync, with your changes kept on this device and <strong>Try again</strong>. A remembered device that was signed out elsewhere now forgets its saved unlock sooner: a session revoked on another device, or a deleted account, removes it the next time this browser checks with the server &mdash; when ZIGoals starts, when its page is shown again or focused, and every 15 minutes while the page stays open and visible. The check is the usual sign-in status request, sends nothing new and never runs in the background; the records on this device stay.</p></HelpQuestion>
        <HelpQuestion id="ad-restore" question="What is new in Restore from a backup?"><p>Settings &rarr; Your data &rarr; <strong>Restore from a backup</strong> now says plainly what is wrong with a file and changes nothing: a damaged file, one that isn&rsquo;t an &ldquo;Export everything&rdquo; ZIP (an encrypted backup, the everything.json from inside one or a single section&rsquo;s backup each say what to choose instead), one made by a newer ZIGoals or by an early test version, and a ZIP that stops part-way. While it runs, <strong>Stop restoring</strong> stops between two parts; what was already restored is listed and can be undone. When the page says so, &ldquo;Undo this restore&rdquo; now also works after a reload, on this device for 7 days, until you use it, choose &ldquo;Keep the restore&rdquo; or change those records. The copy it keeps for this stays in this browser only and is removed then, or the next time you open Settings &rarr; Your data after the 7 days.</p></HelpQuestion>
        <HelpQuestion id="ad-zigi" question="What is new in Meet ZIGi and the Showcase?"><p><Link className="text-link" href="/app/zigi">Meet ZIGi</Link> shows every one of ZIGi&rsquo;s 25 states, grouped by when you see them, each with what it means and when it appears. In the Showcase, &ldquo;On the same days&rdquo; now has enough nights and habit days for &ldquo;Sleep and habits&rdquo;: they come from a fictional earlier season with one Showcase habit, archived since, so it is in none of today&rsquo;s lists or counts.</p></HelpQuestion>
      </Section>
      {/* Session AE (ADR-027): this release's visible changes, each linkable from What's new. */}
      <Section id="ae" updated="Nov 1, 2026 or earlier" eyebrow="TODAY&rsquo;S SCENE, THE SIDEBAR AND WALLETS" title="One scene from top to end, and three finished looks">
        <HelpQuestion id="ae-scene" question="What changed in Today&rsquo;s welcome header?"><p>It is one scene now: the planets are painted straight onto the starfield, with no box and no edge, and run on under the right column and down behind Today&rsquo;s focus. Your words and buttons sit on top of it, and nothing covers what you read or tap. On a phone it is the same idea with the phone&rsquo;s picture. Hide the welcome header with the small arrow in its corner and the scene goes with it, as before.</p></HelpQuestion>
        <HelpQuestion id="ae-finale" question="What happens at the end of each page?"><p>Every page ends in the footer banner, now a short finale. The line runs Goals &rarr; Habits &rarr; Health and, on a wider screen, its pink arc sweeps back into &ldquo;= Wealth&rdquo;, which appears out of a burst of nebula mist; the stars on the planet&rsquo;s rim twinkle and the pink star flares once. It plays once per visit and then rests; with reduced motion or Motion Off it is simply there, still. The banner is see-through, so the starfield shows through its dark space with no edge, and the social links sit right under the three steps.</p></HelpQuestion>
        <HelpQuestion id="ae-themes" question="Are Light and Dark finished now?"><p>Yes: all three looks are finished. <strong>Nebula</strong> stays the default, and its button now shows a small ZG mark. <strong>Light</strong> is Nebula by day: a white page with a light colour mist and dark words, and every colour, chip, chart, ring and glow exactly as in Nebula. <strong>Dark</strong> is a true dark look: flat near-black surfaces with no stars or mist, and Nebula&rsquo;s same colours and contrast. Switching cross-fades briefly (not with reduced motion or Motion Off). Choose one in the theme bar at the bottom of the sidebar, in <Link className="text-link" href="/app/settings#appearance">Settings &rarr; Appearance</Link> or, on a phone, under More. The choice is kept for this device only; <a className="text-link" href="#help-ad-themes">What are Light, Nebula and Dark?</a> says more.</p></HelpQuestion>
        <HelpQuestion id="ae-sidebar" question="Why does the sidebar look different?"><p>Its sky is cleaner: one plain colour behind the logo and the first buttons, then crisp stars from about the middle down, drawn sharp at any window size instead of a stretched picture. It has its own look in each theme: a soft dawn in Light, a flat near-black with no stars in Dark. The planet and the swan at its foot stay as they were. In Nebula and Light its stars drift slowly as you scroll the sidebar (still with reduced motion or Motion Off).</p></HelpQuestion>
        <HelpQuestion id="ae-header-art" question="What are the small drawings in the page headers?"><p>Each page&rsquo;s header now has its own small orbit drawing, in the family of Habits&rsquo; orbit: Goals a lotus opening in a target, Health a heart with a pulse, Wealth a coin with rising bars, Markets candlesticks, the Journey a rocket, Help a question mark drawn as a constellation, and so on. It plays a short entrance once as the page opens (with reduced motion or Motion Off it is simply there, still) and keeps to the header&rsquo;s top-right corner, clear of its words and buttons; on a phone it is small and faint, or left out. It is decoration only. Today keeps its welcome scene instead.</p></HelpQuestion>
        <HelpQuestion id="ae-wallets" question="Can I use a wallet other than Keplr?"><p>Keplr stays the app&rsquo;s wallet, and the one we recommend for ZIGChain. The ▾ beside &ldquo;Connect Keplr&rdquo; (on a phone, in the Status sheet under More &rarr; Status &amp; wallet) holds the rest. <strong>Disconnect</strong> takes the app back to your demo records and asks Keplr to forget this site&rsquo;s ZIGChain Testnet permission. You can also link other wallets <strong>read-only</strong>, only to see their addresses: an EVM wallet such as MetaMask, Rabby or Coinbase Wallet (it is asked only for its account address), Leap or Cosmostation only while still installed (both ended their wallets in 2026), or a Bitcoin address you type (watch-only, checked on your device, nothing sent). Nothing is signed or sent, and a linked address never becomes the app&rsquo;s wallet. Each one has <strong>Remove</strong>; up to 12 can be linked. Linked addresses stay on this device: they are in Export everything, never synced and never restored from a backup. The Showcase keeps its simulated wallet.</p></HelpQuestion>
        <HelpQuestion id="ae-wallet-card" question="What does Today&rsquo;s wallet card show now?"><p>The app&rsquo;s own wallet or, once you have linked one, a linked wallet: the card has a chooser for that, and a switch for the balance in ZIG, USD, EUR or BTC; both choices are kept on this device. The practice money of your demo records and testnet ZIG have no market value, so in USD, EUR or BTC the card reads &ldquo;unavailable&rdquo; and says why. A linked wallet shows its address, read-only; its balance arrives with the staking session. The &ldquo;1,000 ZIG demo balance&rdquo; line has left the top bar and a phone&rsquo;s Status sheet: this card shows the simulated balance instead.</p></HelpQuestion>
        <HelpQuestion id="ae-habits" question="What changed in Habits?"><p>Each time-of-day group (Morning, Afternoon, Evening, Anytime) now has the same room above its first cards as below its last. <strong>Routines</strong>, together with Your stacks, is its own block: by default it sits below the groups, and you can move it like the page&rsquo;s other blocks (unlock the layout with the lock button, then drag its handle or use its arrows). A layout you arranged before keeps its order, with Routines right after your habits.</p></HelpQuestion>
        <HelpQuestion id="ae-music" question="Why does the music button look like ZIGi&rsquo;s?"><p>It is ZIGi&rsquo;s twin now: the same circle, rim and glow, with a music note drawn in the nebula colours, in one column with ZIGi&rsquo;s button, just above it. Tucked away, its edge tab matches ZIGi&rsquo;s too. On a phone ZIGi stays the one floating button, and the music player opens from its menu.</p></HelpQuestion>
      </Section>
      <Section id="af" updated="Nov 5, 2026" eyebrow="EARN, STAKING AND THE CHECKLIST" title="Earn, stake in your own wallet, and your day as one path">
        <HelpQuestion id="af-earn" question="What is the Earn page?"><p>Earn explains every way to earn in the ZIG Finance ecosystem, in plain words, and helps you start: what each way is and who runs it, its live numbers with their source and when they were read (or &ldquo;unavailable&rdquo; with the reason), its fees, lockups and risks, and the steps you take on that app&rsquo;s own site. Ecosystem apps open in a new tab through verified links. ZIGoals never ranks them by rate, never holds your money and never signs for you.</p></HelpQuestion>
        <HelpQuestion id="af-staking" question="Can I stake ZIG from ZIGoals?"><p>Yes, from the Staking page, in your own Keplr wallet. Choose the <strong>practice</strong> network (testnet tokens, no value) or the <strong>real</strong> one (real ZIG; the first time, ZIGoals asks you to confirm). You can stake, unstake, move stake to another validator and claim rewards. Before anything is signed, a review screen shows the action, the validator, the amount you typed, the fee and what unstaking means (21 days before the ZIG is free), and you sign it in Keplr. ZIGoals never sees your keys and sends nothing on its own. Verify, don&rsquo;t trust: Keplr shows the same message again before you sign.</p></HelpQuestion>
        <HelpQuestion id="af-governance" question="Can I vote on ZIGChain proposals from ZIGoals?"><p>Yes, on the Governance page, if you have ZIG staked with an active validator on that network. Each proposal is shown in plain words with its deadline and the tally so far, against the chain&rsquo;s quorum, threshold and veto. You choose Yes, No, Abstain or No with veto, review it, and sign it in Keplr. A vote is public and tied to your address forever, and the review screen says so before you sign. Practise first: the practice network votes for real but with no value. ZIGoals keeps a note of your vote on this device, because the chain stops showing votes once it counts them. Governance is not in the menus until you show it under Settings &rarr; Your pages &amp; buttons (on this device); Earn links to it either way.</p></HelpQuestion>
        <HelpQuestion id="af-practice-badges" question="What are practice badges?"><p>An optional way to put an achievement on the practice network (testnet) only, off unless you switch it on in Staking. It is a tiny transaction to your own address whose note holds only a random badge number or a salted code &mdash; never a goal name or anything you wrote, which stays on this device. Like every transaction it is public forever. ZIGoals never does this on the real network.</p></HelpQuestion>
        <HelpQuestion id="af-start-here" question="How does Start here on Earn work?"><p>Six steps, from no wallet to staking on the real network, if you choose to: get a wallet, practise on the practice network, add money, get ZIG, stake on the real network, then explore liquid staking, pools and governance. A step turns done when ZIGoals can see it from your linked or connected wallet (read-only); a step it cannot see offers &ldquo;Mark as done&rdquo;. Practice never ticks a real step.</p></HelpQuestion>
        <HelpQuestion id="af-academy" question="What is the Earn Academy?"><p>Eight short lessons with three questions each: staking, APR and APY, unbonding, liquid staking, liquidity pools and impermanent loss, copy trading and who holds the money, spotting scams, and gas and fees. Your progress stays on this device; with the game layer on, a lesson you pass earns XP once.</p></HelpQuestion>
        <HelpQuestion id="af-earn-dock" question="What is the Earn dock?"><p>An optional round button on a computer, above the music button on the right edge, that opens the ecosystem apps&rsquo; sections on Earn. It is off until you turn it on in Settings &rarr; Your app &rarr; &ldquo;Earn dock&rdquo; (that switch shows once you use the money and chain pages, see Earn, Staking, Ecosystem and Chess); there you can also tuck it into the edge. Phones and tablets have no floating button: Earn is in Apps &amp; extras, and the index at the top of the Earn page leads to each app&rsquo;s section.</p></HelpQuestion>
        <HelpQuestion id="af-validator-alerts" question="What are validator alerts?"><p>On the Staking page, a note when a validator you stake with is jailed (paused by the network after a fault), misses blocks, stops being active or changes its commission. They are worked out on this device from the chain&rsquo;s public data; ZIGoals sends no notifications. Switch them off in Settings (the switch shows once you use the money and chain pages).</p></HelpQuestion>
        <HelpQuestion id="af-wallets" question="Which wallets can I link, and what does ZIGoals read?"><p>Keplr stays the wallet that signs. You can also link MetaMask, Rabby, Coinbase Wallet, Trust, OKX and Phantom read-only, and type a Bitcoin address. ZIGoals reads only public balances: your browser asks each chain&rsquo;s public service directly, and Wealth and Portfolio show them with their source and time. On a phone, &ldquo;Open ZIGoals in&nbsp;&hellip;&rdquo; opens the app inside that wallet&rsquo;s own browser; pairing by QR arrives once ZIGoals has registered it.</p></HelpQuestion>
        <HelpQuestion id="af-add-money" question="How do I add money?"><p>Wealth &rarr; Add money: choose what to buy (USDC, USDT, ETH, SOL, BTC, ATOM, or ZIG through ATOM), the network to receive it on, your own address on that network, and a provider (Ramp Network or Banxa). The provider&rsquo;s page opens in a new tab, takes the payment and checks your identity; ZIGoals never sees either and never holds the money. Back here you see what happens next and how to bring it to ZIGChain.</p></HelpQuestion>
        <HelpQuestion id="af-goal-vaults" question="What is a Goal Vault?"><p>A Wealth goal linked to stake you already hold in a linked wallet. The goal moves as your stake and its rewards grow, measured from the day you linked them. Nothing moves and nothing is signed: the stake stays in your wallet, and the link stays on this device. Any projection is labelled an illustration.</p></HelpQuestion>
        <HelpQuestion id="af-brief" question="What are the morning brief and the evening recap?"><p>ZIGi&rsquo;s brief is your day from your records: what is open, your Checklist, meals planned, timers running, goal steps and what your money earned, made on this device without an AI. From 18:00 the evening recap says what you did and one thing for tomorrow. Turn either off in Settings &rarr; ZIGi &rarr; Your day; /brief and /recap show them in the chat. ZIGi reads one aloud only when you tap Read aloud.</p></HelpQuestion>
        <HelpQuestion id="af-zigi-checklist" question="Can I tick my Checklist by voice?"><p>Say or type &ldquo;mark push-ups done&rdquo;, &ldquo;vink push-ups af&rdquo;, &ldquo;add read 5 pages to my checklist&rdquo; or &ldquo;start my sleep timer&rdquo;. ZIGi shows the card; nothing changes until you add it.</p></HelpQuestion>
        <HelpQuestion id="af-plans" question="What is a ZIGi plan?"><p>Ask &ldquo;set me up for a 10k&rdquo; and your AI proposes one plan: a few ordinary cards under one heading. Add the steps you want, edit any, or skip the rest. Settings &rarr; ZIGi&rsquo;s plans lists them; Forget removes a plan, not what you added.</p></HelpQuestion>
        <HelpQuestion id="af-page-awareness" question="What does ZIGi see of my page?"><p>For &ldquo;This page&rdquo;, only the page&rsquo;s name and its cards&rsquo; titles, never a number. Nothing on Settings; Health cards only while Health is shared. You can leave &ldquo;This page&rdquo; out of any question. The records that go with a question are a separate choice: see the next answer.</p></HelpQuestion>
        <HelpQuestion id="ai-what-sent" question="What does my own AI receive, and how do I switch ZIGi off?"><p>With no AI connected, nothing leaves this device: ZIGi answers from your records here. Once you connect your own AI, a question goes to it with the records it needs from the pages that share data, figures included (amounts, minutes, counts), never account numbers, wallet addresses or keys. Today, Goals, Habits, Wealth and Help share by default; Health shares only when you turn on Include Health. Settings &rarr; ZIGi &rarr; What each page may share turns any page off, and Turn off ZIGi switches the assistant off completely. Nothing changes in your records unless you add a card yourself.</p></HelpQuestion>
        <HelpQuestion id="af-earn-coach" question="What does ZIGi&rsquo;s Earn coach do?"><p>It explains each way to earn and its words (APR, unbonding, slippage and more) with the figures the Earn page read, each with its source and time, never ranked by rate. It can fill in the staking review for you; you check it and sign in your own wallet. ZIGi never signs, sends or broadcasts anything.</p></HelpQuestion>
        <HelpQuestion id="af-zigi-memory" question="What does ZIGi remember now?"><p>Only notes you agree to keep: the first Remember card asks, and &ldquo;Notes from ZIGi&rsquo;s cards&rdquo; in What ZIGi knows turns it off. Notes stay on this device and are in Export everything.</p><p>Restore from a backup brings back ZIGi&rsquo;s and NOVA&rsquo;s memory; notes filed under Health or Diet come back only if you choose the Health part. Merge adds only missing notes; Replace takes the backup&rsquo;s; Undo puts it back.</p></HelpQuestion>
        <HelpQuestion id="af-universe" question="What is My universe?"><p>One planet for each part of your life, growing from your own records: rings, moons and today&rsquo;s light. Nothing is ever taken away; a missed day leaves a faint ring. It lives on Journey, with the game layer on or off, and on Today. Only which milestones were celebrated is kept, on this device.</p></HelpQuestion>
        <HelpQuestion id="af-timeline" question="What is the Day timeline?"><p>Today on one line: habits, meals, sleep, a running fast, timers, reminders and your Checklist&rsquo;s dots. Tap to complete; drag, use the arrow keys or Change time to move a habit or a meal. Times you move stay on this device; your habits and reminders keep their own.</p></HelpQuestion>
        <HelpQuestion id="af-stories" question="What are Stories?"><p>Your week, month and year as a few cards from your own records, each shareable as an image made on this device, with counts only &mdash; never an amount, a price or a return. A story needs three logged days, and it moves on only when you tap.</p></HelpQuestion>
        <HelpQuestion id="af-checklist" question="What is the Checklist?"><p>Your day as one path of glowing dots: the habits, goal steps and health inputs you starred, in your order, grouped in orbits (Morning, Afternoon, Evening, Anytime, or your own). Open it from the Checklist button on a computer, from the Checklist pill in the header on a phone (or More, or Today&rsquo;s Checklist card), or from the Home Screen shortcut. It starts fresh at local midnight, and yesterday stays in its history.</p></HelpQuestion>
        <HelpQuestion id="af-checklist-star" question="How do I put something on my path?"><p>Tap the star on a habit, a Goal&rsquo;s next step, a milestone, Water, a familiar food or supplement, a meal, the weight journal, sleep, meditation or fasting. Filled in the item&rsquo;s own colour means it is on your path; tap again to take it off, with Undo in the message. In the Checklist, <strong>Edit path</strong> adds your own items (like &ldquo;Play piano 15 minutes&rdquo;), removes and reorders them, and can turn one into a habit.</p></HelpQuestion>
        <HelpQuestion id="af-checklist-tick" question="What happens when I tick a dot?"><p>The planet lights up &mdash; its matte ring turns to full colour, its mark glows in the nebula colours and its name gets a check &mdash; a light runs along the line to the next one, and the real record is written on its own page: a habit check-in, a goal step, water, a diary entry, a weight, a night, mindful minutes or a fast. Undo puts that record back exactly. Tick in any order. Water, weight and count habits open a small stepper with your usual value.</p></HelpQuestion>
        <HelpQuestion id="af-checklist-streak" question="How does the Checklist streak work?"><p>A day counts when every dot on your path is done, whenever you tick them. Rest days (not scheduled, paused or skipped) are left out, never failed. Ticking every dot in path order earns &ldquo;Perfect orbit&rdquo;. With the game layer on, Checklist days earn the First orbit, Seven orbits and Perfect orbit badges (never XP), and a streak freeze mends a missed day.</p></HelpQuestion>
        <HelpQuestion id="ag-orbit" question="Why does the Checklist look different?"><p>Each planet is now a glowing ring with its own mark and colour, lit once it is done, with its name on a small tab. One flowing line runs through your whole day, from orbit to orbit. The timers are slim cards that show your own goal, or say plainly what their number is when you have not set one. The sky is the same as on your other pages. The chests are gone, and the Checklist no longer adds XP, so your game-layer total can be a little lower than before; your badges, streak and Perfect orbit stay.</p></HelpQuestion>
        <HelpQuestion id="ag-polish" question="What&rsquo;s new in the Checklist?"><p>Every orbit opens with its own planet on the line; it lights up with a short animation once you reach it. The orbits wear the same banners as your Habits page. Planets not yet done are matte, and every mark is drawn in the nebula colours. On a phone the path is longer and airier, every name fits on one line, and a Checklist pill in the header opens it in one tap. Finishing your day always plays its celebration, however you finished it &mdash; once a day on this device; &ldquo;Replay today&rsquo;s celebration&rdquo; is in the menu. The List view groups your items by orbit, with a &ldquo;Done&rdquo; fold and a quick &ldquo;+&rdquo; for items you log more than once.</p></HelpQuestion>
        <HelpQuestion id="ag2-quick-add" question="How do I add something to my Checklist quickly?"><p>Tap &ldquo;+&rdquo; at the top of the Checklist, beside &ldquo;⋯&rdquo;. Give it a name, then choose its orbit (Morning, Afternoon, Evening or Anytime), how you count it (once a day, a number with its unit, or minutes), its days and, if you like, a colour; the node it becomes shows as you type. &ldquo;Add to my orbit&rdquo; makes it a real habit on your Habits page, in the same time of day, and puts it on your path; the message that follows links to it on Habits. Undo takes back both while the habit is untouched; once it has changed, Undo only takes it off your orbit and the habit stays on Habits.</p></HelpQuestion>
        <HelpQuestion id="ag2-planets" question="When does an orbit&rsquo;s planet light up?"><p>When you reach it. The day&rsquo;s first planet lights as soon as you tick anything in its orbit; each next planet lights once everything in the orbit before it is done. It plays its short animation at that moment, once; Undo makes it matte again. The orbit&rsquo;s banner still says &ldquo;Complete&rdquo; only when every item in it is done.</p></HelpQuestion>
        <HelpQuestion id="ag2-progress" question="What does the bar at the top of the Checklist show?"><p>One segment for each item that counts today, in your path&rsquo;s order and colours. A segment lights the moment you tick its item, even out of order, and the sparkle sits at the end of the last lit one. The words beside it say how many planets are lit today.</p></HelpQuestion>
        <HelpQuestion id="ag2-celebration" question="What happens when I finish my day?"><p>A short film plays: ZIGi with your day&rsquo;s planets in orbit, then your own words &mdash; how many planets are lit, your streak and Continue. It plays without sound, once a day on this device, and a tap skips to its end. With reduced motion, Motion Off or Data Saver, or when it cannot start quickly, you see its last frame at once. Undo waits until you close it. &ldquo;Replay today&rsquo;s celebration&rdquo; is in the menu.</p></HelpQuestion>
        <HelpQuestion id="af-checklist-timers" question="What are the timers in the corner of the Checklist?"><p>Sleep, Meditate and Fast (and Focus, when a timed habit is on your path) start and stop the page&rsquo;s own timer in one tap. Tap Sleep at bedtime and again when you wake: the whole night lands on Health. A card says &ldquo;Goal&rdquo; only for a goal you set; otherwise it says what its number is.</p></HelpQuestion>
        <HelpQuestion id="af-checklist-launcher" question="Where is the Checklist button, and can I hide it?"><p>On a computer it sits with ZIGi&rsquo;s and the music button on the right edge, between Music and ZIGi; its arrow tucks it into the edge. Settings switches it off on this device. Phones keep ZIGi as the one floating button and show a Checklist pill in the header instead (the same setting hides it); the Checklist is also in More, on Today&rsquo;s card and on the Home Screen shortcut. Your path stays on this device: it is not synced yet.</p></HelpQuestion>
      </Section>
      {/* Session AJ (ADR-035): the big leap, one answer per What's new link. */}
      <Section id="aj" updated="Nov 1, 2026 or earlier" eyebrow="ALERTS, JOURNEYS AND YOUR OWN LOOK" title="Price alerts, Guided journeys, sleep balance and your own look">
        <HelpQuestion id="aj-alerts" question="How do price alerts and net worth by source work?"><p>On a coin&rsquo;s Portfolio page or a goal&rsquo;s page, set an alert for a price above or below a figure, or for when a coin puts a goal at a percent. ZIGoals checks it with the prices the app already reads, when the app opens and when prices refresh; a reached alert shows once, waits on Today until you tap Seen, and is listed in Activity. Alerts stay on this device and never buy, sell or move anything. On Wealth, &ldquo;By source&rdquo; in the history chart shows how much came from market prices, values you entered, wallets, exchanges and staking; readings from before this update show as &ldquo;Source not recorded&rdquo;.</p></HelpQuestion>
        <HelpQuestion id="aj-guided" question="What are Guided journeys, Focus Sessions and the Life Score?"><p>Guided journeys are short programs you choose (an emergency fund, a sleep reset, a walking start&hellip;): one small step opens each day and you tick it yourself; nothing is created for you. Find them from Goals, Habits, My Universe or search. Focus Sessions, on Journey, grow a sprout while the page stays in front; a web page cannot block other apps, so time with the page hidden counts as away, and a session ended early is kept as withered. The Life Score on My Universe is off until you turn it on: a number from 0 to 100 for the last two weeks of your own records, with the reasons per part of life; a part with no records is left out, never counted as zero.</p></HelpQuestion>
        <HelpQuestion id="aj-health" question="What are sleep balance, the focus window and GPX import?"><p>Sleep balance, in Health &rarr; Sleep, compares your time asleep with your own goal over the last 14 days, on average per night, in plain words. &ldquo;Your best focus window today&rdquo; on Today is an estimate from last night: many people are most alert some two to four hours after waking; you can turn it off in Health &rarr; Sleep. In Workouts you can import a GPX or TCX file from your watch or app: it is read on this device and only its summary (time, distance, climb, average heart rate) is kept, never the route. None of this is medical advice.</p></HelpQuestion>
        <HelpQuestion id="aj-wealth" question="What are trader tools, and how do I watch a Bitcoin wallet by its public key?"><p>Trader tools, on a portfolio with sales (Insights), are off until you turn them on: wins and losses, how long you held what you sold, fees, results by month, a gentle check after a run of losses or late-night sales, and a cost-of-leverage illustration. They are information, not advice. To watch a whole Bitcoin wallet, choose &ldquo;Watch a Bitcoin wallet (xpub)&rdquo; in the wallet menu and paste its xpub, ypub or zpub (never a private key). The key stays on this device; its addresses are worked out here and read from mempool.space, which sees them.</p></HelpQuestion>
        <HelpQuestion id="aj-look" question="How do I change the app&rsquo;s look, or erase everything on this device?"><p>Settings &rarr; Appearance &rarr; Customize: the font (System or Inter), the text size (Standard or Large), the density (Comfortable or Compact) and the glow (Full or Soft), on this device only. Settings &rarr; Backup &amp; restore ends with &ldquo;Erase everything on this device&rdquo;: after you type ERASE it removes every ZIGoals record from this browser. Make Export everything first if you want a copy; nothing on a blockchain or another device changes.</p></HelpQuestion>
        <HelpQuestion id="aj-v6" question="Why did the network fee change when I stake?"><p>ZIGChain&rsquo;s practice network moved to version 6, which prices transactions with a base fee that can rise when blocks are busy. ZIGoals reads it when it prepares your review, shows the gas price it used, and your wallet signs exactly that fee; if your wallet changes it, nothing is sent. Voting needs at least 1 ZIG staked with active validators. Mainnet follows when its own upgrade happens.</p></HelpQuestion>
      </Section>
      {/* Session AK (ADR-036): this release's answers, one per feature group, mirrored in lib/search/static.ts. No link sits
          inside an answer's sentence (Help's in-sentence link count is pinned); Known limitations points here instead. */}
      <Section id="ak" updated="Nov 1, 2026 or earlier" eyebrow="OFFLINE, FOOD, MONEY AND MORE" title="Notifications, offline, food, money and your own days">
        <p>A lot arrived at once, and all of it is optional. The short tour shows seven of the biggest in about a minute; each stop has a &ldquo;Show me&rdquo; link.</p>
        <TourOffer/>
        <HelpQuestion id="ak-notify" question="How do notifications on this device work?"><p>Settings &rarr; Notifications turns them on for one device, with a switch per kind (habits, water, wind-down, contributions, bills, price alerts and the weekly review), your morning and evening times and quiet hours. No account is needed. The words are written on this device from your own records: the notification service only learns when to wake this device (a random id, your time zone, your quiet hours and the minutes to wake), never what a reminder is for, and every message it sends is empty. &ldquo;Done&rdquo; and &ldquo;Snooze 1 h&rdquo; on a notification apply when ZIGoals next opens, with Undo. On an iPhone, notifications need ZIGoals installed on the Home Screen. On this Alpha the card says &ldquo;Being switched on&rdquo;: nothing reaches your phone yet, and the choices you make there are kept ready.</p></HelpQuestion>
        <HelpQuestion id="ak-offline" question="Does ZIGoals work offline now?"><p>Yes, for the pages you have opened before. Settings &rarr; Install ZIGoals installs it on any device: a button where your browser offers one, or the Share &rarr; Add to Home Screen steps on an iPhone or iPad. Pages you have visited on this device then open without a connection, and what you record is saved on this device as always. A food lookup or an exchange refresh you ask for while offline waits on this device for up to a week and is offered again when you are back online; nothing runs by itself. The offline copies hold the app&rsquo;s pages, never your records, and Erase everything clears them. When a new version is ready, a short note offers to reload.</p></HelpQuestion>
        <HelpQuestion id="ak-wallets" question="Can I link a wallet on my phone?"><p>Yes, by WalletConnect, from the wallet menu: on a phone each wallet app has its own button, and on a computer a QR code lets the wallet on your phone scan it. MetaMask, Trust, OKX and Ledger Live link read-only: ZIGoals reads their addresses and balances and asks for nothing else. Keplr Mobile can also sign staking over WalletConnect, always through the same review screen, and only where it supports ZIGChain. ZIGoals never holds keys and never moves anything on its own. Until WalletConnect has approved ZIGoals&rsquo; web address, the panel says that phone wallets are being switched on.</p></HelpQuestion>
        <HelpQuestion id="ak-food" question="What changed in food logging?"><p>In Health&rsquo;s food diary, Recent scans keeps the barcodes you scanned on this device, so a food comes back in one tap with the same amount and meal. A food is looked up in the food library first: generic foods from the French CIQUAL and British CoFID tables, downloaded once and kept on this device, so they work offline. After that come Open Food Facts and, for what it doesn&rsquo;t know, USDA FoodData Central, through ZIGoals&rsquo; food service; only the barcode or the words you type are sent. The Nutri-Score letter is off until you turn it on beside the barcode lookup, and is always written out, never shown by colour alone. With your own AI connected to ZIGi (a model that reads photos, with Health shared with ZIGi), &ldquo;Read the label from a photo&rdquo; fills in a new food from its label, and &ldquo;Estimate a meal from a photo&rdquo; gives an estimate you check before anything is saved; the photo goes only to your AI, with that one request. Keeping a meal&rsquo;s photo beside its estimate is off until you choose it, and those photos stay on this device. Export everything includes them as files, but Restore from a backup does not bring them back. Every number read from a photo is an estimate.</p></HelpQuestion>
        <HelpQuestion id="ak-nutrition" question="What are the nutrient report, diet templates, the pantry and the weekly calorie budget?"><p>The Nutrient report, opened from Micronutrients, shows a day&rsquo;s totals or your 7-day averages against reference values that are general guidance, and &ldquo;Where it came from&rdquo;: the foods that gave you most of each nutrient over 7, 30 or 90 days. A nutrient with no value is left out, never counted as zero. In the planner, a diet template (Mediterranean, high-protein or vegetarian) fills a week only after you review it and choose &ldquo;Add to this week&rdquo;, and Undo takes it back. On the grocery list, &ldquo;I have this&rdquo; moves an item to &ldquo;Already at home&rdquo;; your ticks stay on this device. The Weekly calorie budget shows your own daily target as seven days, lets you shift calories between days (the week&rsquo;s total stays the same) and, if you like, roll over a past day&rsquo;s unused calories. It is a view of your own target, not advice.</p></HelpQuestion>
        <HelpQuestion id="ak-music" question="What can the Music page do?"><p>Open it from the Music button. &ldquo;Your mix&rdquo; layers up to three sounds made on this device, each with its own level, starting from Focus, Wind down or Sleep, with a sleep timer that fades out gently. &ldquo;In your music app&rdquo; opens focus, deep-work, sleep and workout playlists in Spotify, Apple Music or YouTube Music: plain links, and nothing about you is sent. If you like, you can use your own Spotify app; its id stays on this device. Focus Sessions can play a focus sound, and the wind-down reminder a calm one.</p></HelpQuestion>
        <HelpQuestion id="ak-habits" question="What&rsquo;s new in Habits?"><p>Sort by &ldquo;Your order&rdquo; and choose Reorder: move a habit with its Move up and Move down buttons, with Alt and the arrow keys, or by dragging it with a mouse. Compact shows each habit as one row with its last five days, one tap per day, with Undo. &ldquo;Done automatically&rdquo; holds rules such as &ldquo;When steps &ge; 8,000 &rarr; Walk is done&rdquo; or &ldquo;When I log a workout &rarr; Gym is done&rdquo;: a rule ticks a day once, only from records on this device, never from a day with nothing recorded, and your own tap or Undo always wins. A routine can play full screen, one step at a time, and can be shared as a small file (step names only if you tick them); adding a shared routine only ever adds new habits. When you make a habit, &ldquo;Type it&rdquo; reads a schedule written in words and shows what it understood; words it doesn&rsquo;t know are marked, never guessed, and nothing changes until you use it.</p></HelpQuestion>
        <HelpQuestion id="ak-goals" question="What&rsquo;s new for Goals?"><p>On a goal&rsquo;s page, &ldquo;What if&rdquo; shows how the estimated date moves with a regular amount, a habit that adds to it or a target date, beside your pace over the last 30 days: a projection from your own data, never a guarantee. &ldquo;Share your progress&rdquo; makes an image on this device with the goal&rsquo;s name and percentage; amounts and the target date appear only if you tick them, and nothing is uploaded. Under a goal&rsquo;s milestones, a suggested set for that kind of goal can be added step by step, and habits can be linked to each milestone. In Quick add, a sentence such as &ldquo;save &euro;5,000 for a trip and walk 8k steps most days&rdquo; becomes one review card with each part: only what you confirm is made, and the goal is saved only when you create it in the Goal wizard. Nothing moves money.</p></HelpQuestion>
        <HelpQuestion id="ak-wealth" question="What are bills, budgets, the target mix and the contribution rhythm on Wealth?"><p>Upcoming bills lists what is due in the next 30 or 60 days, from bills you add or confirm from a repeat in your spending, with a total per currency and an estimated monthly figure. It is a reminder only: ZIGoals never pays or cancels anything. Budgets by category set a monthly amount per category against what your money log shows spent, with optional rollover. Your target mix sits beside today&rsquo;s mix, one currency at a time, and says how far each share is from your target, never what to buy or sell. &ldquo;What each asset is for&rdquo; draws your assets flowing to the Goals they are set aside for, with the same numbers as a table. Your contribution rhythm says when you usually add to a goal and offers a reminder or the goal&rsquo;s own form, filled in for you to check. A connected exchange refreshes itself every 15 minutes while ZIGoals is open and shows when it last synced. Amounts in different currencies are never converted, and none of this is advice.</p></HelpQuestion>
        <HelpQuestion id="ak-money-tools" question="What are Money tools, and can I import a bank file?"><p>Money tools sit under Wealth &rarr; Spending. Buffer days says how many days your cash would cover your usual spending, or why it can&rsquo;t say yet. Rules set a category, a new name, a tag or a Goal for entries whose payee or memo matches plain text (the first rule that matches wins); &ldquo;Apply to the past 90 days&rdquo; shows every change first, with Undo. &ldquo;To review&rdquo; lists what an import added for you to accept; reviewing never changes an amount. &ldquo;Split an entry&rdquo; divides one entry into two to five parts that must add up exactly. The emergency sheet is a page to print for people you trust, with your accounts and where the documents are; it refuses to print anything that looks like a key or recovery words. The import sheet also reads bank statement files (CAMT.053, OFX or QFX, MT940) and offers CSV templates to fill in: the file is read on this device, never uploaded, there is no bank connection, and you confirm a preview before anything is added. All of it stays on this device.</p></HelpQuestion>
        <HelpQuestion id="ak-plan" question="What are the fee drag and financial freedom calculators?"><p>Both sit beside the compound interest calculator. Fee drag compares the same amount and the same yearly return with two different yearly fees, and shows the gap at the end; nothing is stored. Financial freedom works out a target from your yearly spending and a withdrawal rate, then runs 1,000 possible paths from your invested amount, monthly contribution, expected return and ups and downs, and shows the middle path and the range most paths fall in. Its inputs are kept only when you ask. Both are models from your own numbers, not advice, and no result is a guarantee.</p></HelpQuestion>
        <HelpQuestion id="ak-review" question="What are review notes, the Daily orbit card, share cards and the rewards shelf?"><p>The Life review now adds one line per part of life and a short note from ZIGi on your week or month, made on this device from your records with no AI service; it names a pairing, never a cause. The Daily orbit card, which you can add to Today, shows how much of today&rsquo;s orbit is lit, the next three things due and one way into the Checklist; it only reads. Share cards make an image on this device of what you choose; amounts and Health values are off until you tick them, and a Showcase card says &ldquo;Example&rdquo;. On Journey, badges are a choice of their own, and the rewards shelf, off until you turn it on, lets you list treats with a price in the points you already earn and mark one as enjoyed, with Undo. No penalties, nothing is ever taken away, and what is left never goes below zero.</p></HelpQuestion>
        <HelpQuestion id="ak-days" question="What are feeling words, Compare, the energy curve, the year in pixels and the report for a visit?"><p>After the 1&ndash;5 energy or mood in the daily check-in or the Journal, you can pick a feeling word for the day; it is optional and stays with your energy record. Health &rarr; Insights &rarr; Compare puts a factor beside an outcome on the same or the next day, shows the counts first, and only says more with at least 14 days on each side and a clear difference; it is a pairing, not a cause. Health &rarr; Sleep &rarr; &ldquo;Your energy today&rdquo; draws an estimated alertness curve from your sleep times, with your likely focus window and dip; nothing is stored, and it is not medical advice. Journal &rarr; Year shows a year of your days as small squares by mood or energy, each with a label in words, and can be saved as an image. Settings &rarr; Your data &rarr; &ldquo;Report for a visit&rdquo; makes a printable summary of the dates and parts you choose, made on this device from records already here; nothing is uploaded or kept.</p></HelpQuestion>
        <HelpQuestion id="ak-chess" question="Can I play Lichess inside ZIGoals?"><p>Yes. In Chess, &ldquo;Play on Lichess here&rdquo; connects through Lichess&rsquo;s own sign-in page; the access it gives stays on this device and goes only to lichess.org. Connected, you can look for a rapid or classical game, challenge a friend, play the Lichess computer, and see your ongoing games and the challenges sent to you. On a phone your games are listed with &ldquo;Continue on Lichess&rdquo; instead of the board. The Lichess daily puzzle needs no sign-in: solve it without a hint and the chess habit you chose is ticked off, once a day.</p></HelpQuestion>
        <HelpQuestion id="ak-switch" question="Can I bring my data from Daylio, Habitica, YNAB, Strong or Hevy?"><p>Yes, from Settings &rarr; Switch to ZIGoals for Daylio, Habitica and YNAB, and from Workouts for Strong and Hevy, beside GPX, TCX and FIT files and Strava&rsquo;s whole-account export. Each file is read on this device into a preview, and nothing is written until you confirm; &ldquo;Undo this import&rdquo; right after removes exactly what it added. Daylio moods go to Health only when you tick them. Garmin workouts come in as FIT files exported from Garmin. Workouts also gained supersets, effort (RPE), a plate calculator, rest timers and records, and a muscle-group view of how fresh each group is: an estimate from your own sets, with recovery days you can change.</p></HelpQuestion>
        <HelpQuestion id="ak-data" question="What are Test a backup, the backup reminder and taking my data to another app?"><p>In Settings &rarr; Your data, &ldquo;Test a backup&rdquo; checks an Export everything ZIP by restoring every part in a sandbox; nothing on this device is read or changed. &ldquo;I saved a copy today&rdquo; records when you last made a backup, and when a month passes without one, Settings &rarr; Your data says so (you can turn that off). &ldquo;Take your data to another app&rdquo; says honestly what other apps can read: Loop Habit Tracker gets a file it really imports, and for the others ZIGoals names what they accept and offers plain CSV. Point &amp; tell notes now describe what you picked by its role and the page, never the words on it. The Checklist can travel as an optional, encrypted part of your sync once the sync service is updated; until then it stays on this device.</p></HelpQuestion>
        {/* Owner follow-up 1 (F4, F5, BUILD list 2): one answer per area, each saying what is stored and what is only shown. */}
        <HelpQuestion id="ak-agenda" question="Where can I see everything coming up, and can I put it in my own calendar?"><p><Link href="/app/agenda">Agenda</Link> (from Today&rsquo;s day timeline card or Search) shows habits, planned contributions, bills, workouts, meal plans, unstaking dates and reviews by day, week or month. Nothing is ticked off there: tap an item to open it where it lives. &ldquo;Export to a calendar&rdquo; makes an .ics file on this device for the days and kinds you choose; it holds titles and days only unless you add the details, and nothing is uploaded. Search can also do things: type &ldquo;log water&rdquo; or &ldquo;open agenda&rdquo;, or start with &ldquo;&gt;&rdquo; for actions only. An action opens the right place; nothing is saved until you confirm there.</p></HelpQuestion>
        <HelpQuestion id="ak-money-more" question="What are the debt planner, savings challenges and net-worth milestones?"><p>On Wealth, &ldquo;Plan paying off your debts&rdquo; compares snowball (smallest balance first) and avalanche (highest rate first) from your own debts: the month you would be debt-free and the interest each saves. It is a model, not advice. Goal templates include 52-week, no-spend-days and round-up challenges; their progress comes only from what you record and log, and nothing moves money. Net-worth milestones are off until you turn them on; the first time you pass one, a quiet card says so, once. Financial freedom: your target is yearly spending divided by the withdrawal rate, and the shaded band is the middle 8 in 10 of 1,000 possible paths, never a promise.</p></HelpQuestion>
        <HelpQuestion id="ak-health-more" question="Supplements, measurement trends and habit plans: what is new?"><p>Health &rarr; Diary can keep an optional supplements and medication log: names, a dose in your words, times and days, taken or skipped. It gives no medical advice and checks no doses; its reminders are off until you turn them on and never name what you take, even when names are allowed. Body measurements show their trend and the week&rsquo;s change (a description, not a forecast), and progress photos have a before/after slider; both stay on this device. On a habit, &ldquo;when and where&rdquo; keeps your plan (&ldquo;After I pour coffee, in the kitchen&rdquo;), stacks chain habits in order, a weekday habit can be &ldquo;first Monday of the month&rdquo;, and ZIGoals may offer the time you usually check in, set only if you tap it.</p></HelpQuestion>
        <HelpQuestion id="ak-journal-more" question="What are On this day, Experiments, Your first week and ZIGoals Wrapped?"><p>On this day (Journal) shows what you wrote on this date in earlier years, or a month ago; hide one memory with &ldquo;Not this one&rdquo;, or all of it under Journal &rarr; Privacy. Experiments (Health &rarr; Insights) let you try one change for 14, 21 or 28 days and compare with the same number of days before, with Compare&rsquo;s rules: at least 14 days a side, what happened together, never a cause. Your first week is an optional Today card (Customize Today): one small step a day for seven days, in any order; skipping costs nothing and Hide ends it. ZIGoals Wrapped tells your year back in a few cards from 1 December, or once your year has 30 logged days (Journey or Search); shared images show counts only unless you include the numbers.</p></HelpQuestion>
        <HelpQuestion id="ak-safety-more" question="Why does ZIGoals warn me about recovery words?"><p>ZIGoals never needs your recovery words or private keys, and nobody helping you should ask for them. If a note, journal entry or ZIGi message looks like one, a calm line says so. You can still save a note (it stays on this device), and ZIGi never sends such a message to an AI. On the ZIGChain pages, &ldquo;What is this token?&rdquo; reads a token&rsquo;s facts from the network itself (no address is sent) and flags names that imitate another token; a proposal&rsquo;s own words are shown shorter and labelled as the proposer&rsquo;s, and a vote reminder you set stays on this device.</p></HelpQuestion>
        <HelpQuestion id="ak-zigi-more" question="What can ZIGi do with the new features?"><p>Ask &ldquo;When will I be debt-free?&rdquo;, &ldquo;What&rsquo;s on my agenda this week?&rdquo; or &ldquo;Which supplements are left today?&rdquo;: ZIGi answers on your device from your own records, even with no AI connected. With your AI, ZIGi can log a supplement, keep your debt planner&rsquo;s figures or start a savings challenge, always as a card you confirm; it never pays or moves money, and those cards are never accepted for you. It can also open the agenda or your Wrapped.</p><p>Ask &ldquo;What was my last blood pressure?&rdquo; or &ldquo;How does my cash look over the next 60 days?&rdquo;: ZIGi and NOVA answer from Your numbers, your cash forecast, your own scales and the cycle log, on this device. With your AI, they can keep a blood pressure reading, rate one of your own scales, or move a task to tomorrow (or let it go), each as a card you confirm, with Undo. A money amount can be a sum, like 12,50+3,20. Readings are never a diagnosis, and the forecast is a model, not a promise.</p></HelpQuestion>
      <HelpQuestion id="ak-sleep-wake" question="Does ZIGoals look at when I wake up as well as when I go to bed?"><p>Yes. Sleep shows your wake-time consistency beside your bedtimes: how much your wake time moves across the week. It is a description of your own logs, not a sleep score or advice.</p></HelpQuestion>
      <HelpQuestion id="ak-warmup" question="Can I log warm-up sets and supersets?"><p>Yes. In a workout, mark a set as warm-up, drop or to failure, group exercises into a superset, note how hard a set felt (RPE), and use the plate calculator. Warm-up sets never count toward records or volume.</p></HelpQuestion>
      <HelpQuestion id="ak-storage-full" question="What happens when storage on this device is nearly full?"><p>ZIGoals checks each of its storage parts as you use it. If one is nearly full, one calm line says so once per visit, with what to do: export everything, then remove old photos or imports. Nothing is deleted for you.</p></HelpQuestion>
      <HelpQuestion id="ak-progress-toast" question="Why does a contribution say how far it moved my goal?"><p>After you record a contribution, a short line says how far it moved that goal (&ldquo;That moved Japan to 42%&rdquo;); &ldquo;at least&rdquo; when some sources have no value, nothing when progress is unknown. It is information, not a promise.</p></HelpQuestion>
      <HelpQuestion id="ak-staking-clarity" question="Where do I see my staking rewards, unstaking dates and practice steps?"><p>On Earn, once a wallet is linked: &ldquo;Rewards, unstaking and history&rdquo; shows rewards waiting to be claimed, an unstaking calendar, rewards you claimed here and a CSV download. Validator choices show each validator&rsquo;s rank by stake and how spread the stake is, with validators outside the ten largest first. On the practice network, &ldquo;Your practice round&rdquo; ticks its steps from your confirmed practice transactions. Nothing here signs or moves anything.</p></HelpQuestion>
      <HelpQuestion id="ak-your-numbers" question="Can I keep my blood pressure and lab values?"><p>Yes. Health &rarr; Measurements &rarr; Your numbers: type blood pressure readings and lab values from your own sheet, or let your own AI copy a photo of the sheet into a draft you check first (the photo is not kept). ZIGoals sets no ranges and gives no interpretation: the only check is inside or outside the range you copied from your sheet. Your readings, not a diagnosis. You can add them to the Report for a visit.</p></HelpQuestion>
      <HelpQuestion id="ak-scales" question="Can I rate my own things, like stress or pain?"><p>Yes. Journal &rarr; Your own scales: up to five 1&ndash;5 ratings of your own, with your own words for each end. Rate them in ZIGi&rsquo;s check-in or the Journal, and skip any day. Health &rarr; Insights &rarr; Compare and Experiments can show what goes with them. Removing a scale keeps its ratings.</p></HelpQuestion>
      <HelpQuestion id="ak-journal-prompts" question="Can the Journal give me something to start from?"><p>Yes. In the Journal&rsquo;s Write box, &ldquo;Start from a prompt&rdquo; offers eight free prompts in English or Dutch (Morning intention, Three good things, Worry then one next step, Gratitude, Week look-back, Before a hard talk, Another way to see it, A letter to future you). Each fills your entry with a few headings to write under. Another way to see it is a reflection, not therapy.</p></HelpQuestion>
      <HelpQuestion id="ak-wrap-up-tasks" question="What does the evening wrap-up do with today&rsquo;s open tasks?"><p>It lists them: move each to tomorrow (its time, priority and goal stay), or let it go (it stays in Tasks without a day). Undo is always there, and nothing is counted as missed.</p></HelpQuestion>
      <HelpQuestion id="ak-focus-bell" question="Can Pomodoro ring a bell between rounds?"><p>Yes. Pomodoro &rarr; Bell and breaks: a soft bell at each change, made on your device and on time even in a background tab, and your focus sound fades during breaks. Only focus blocks count toward your totals.</p></HelpQuestion>
      <HelpQuestion id="ak-cycle" question="Is there a cycle log?"><p>Yes, off unless you turn it on: Settings &rarr; Your pages &amp; buttons &rarr; Cycle log. Then log period days, flow, how it feels and a note in Health &rarr; Diary. After three cycles it shows an estimate range for the next period, from your past cycles. Information for you, not a contraceptive or a diagnosis. It stays on this device, is restored only with the Health choice and never appears in a notification. Hiding it keeps your entries; deleting them asks first.</p></HelpQuestion>
      <HelpQuestion id="ak-motion-calm" question="What are Full, Calm and Off motion?"><p>Settings &rarr; Appearance &rarr; Motion. <strong>Full</strong>: pages glide in, numbers count up once and a finished habit, task or goal gets a short ring of light. <strong>Calm</strong>: a gentle crossfade between pages and the ring alone; nothing loops. <strong>Off</strong>: everything is still; your device&rsquo;s &ldquo;reduce motion&rdquo; setting has the same effect. A short vibration on completion follows the Checklist&rsquo;s vibration switch and is off with Motion Off.</p></HelpQuestion>
      <HelpQuestion id="ak-money-quicker" question="What makes logging money quicker now?"><p>The category chips start with the three you used most in the last 30 days. An amount field takes a sum such as 12,50+3,20 or 3&times;4.99: ZIGoals shows the result and saves it (no result at or below zero). In Spending &rarr; This week, Select entries to see their total; each currency is shown on its own, never converted. In To review, &ldquo;One at a time&rdquo; shows each entry as a big card: Accept (A), Skip (S), Make a rule (R), Undo (Z).</p></HelpQuestion>
      <HelpQuestion id="ak-receipt-photos" question="Can I keep a receipt photo with an entry?"><p>Yes. Money tools &rarr; Receipt photos: each photo is shrunk to 200 kB and kept in this browser only, never uploaded or synced. It is in Export everything and removed by Erase everything. If you connected your own AI, &ldquo;Draft an entry from a receipt&rdquo; fills the Spending form for you to check; nothing is saved until you tap Save.</p></HelpQuestion>
      <HelpQuestion id="ak-cash-forecast" question="What is Next 60 days?"><p>Money tools &rarr; Next 60 days is a model from your own records, not a promise: it starts from your cash and savings balances, then takes away your bills, the repeats it finds in your log and your Goals&rsquo; plans, and adds your usual pace of everyday spending. Each currency on its own, never converted; where your log is too short, it says so instead of guessing.</p></HelpQuestion>
      <HelpQuestion id="ak-spending-map" question="What are the spending map and the net-worth share card?"><p>Spending &rarr; This month by category &rarr; Map shows the month as rectangles sized by category; the table beside it lists the same, and each rectangle opens its entries. Under your net-worth milestones, Share this moment makes an image on this device with the change in per cent; amounts stay off unless you tick Include numbers.</p></HelpQuestion>
      <HelpQuestion id="ak-note-useful" question="What does &ldquo;Was this useful?&rdquo; under ZIGi&rsquo;s note do?"><p>On the Review page, under ZIGi&rsquo;s note on your week or month, one optional tap: <strong>Useful</strong> or <strong>Not for me</strong>, about the line that leads the note (things seen together, a Health measure beside the week before, or your longest streak). &ldquo;Not for me&rdquo; leaves that kind of line out of later notes; a later &ldquo;Useful&rdquo; brings it back, and Undo takes a tap back. It stays on this device and is used for nothing else.</p></HelpQuestion>
      <HelpQuestion id="ak-journal-music" question="Where are Tasks, Notes, the Journal and Music?"><p>On a phone, in More; on a tablet, in the rail; on a computer, in the sidebar when the window is tall enough for them, and always by pressing <kbd>/</kbd> (or Search) and typing the name. The Journal also opens from &ldquo;Open your journal&rdquo; on Today&rsquo;s &ldquo;How was today?&rdquo; card, and Music from &ldquo;Open the full music page&rdquo; in the music player. Tasks are one-off things to do; the Checklist on Today is your daily path, and it stays as it is. The Journal is how the day felt; a note is anything you want to keep (type [[ in a note to link a goal, a habit or another note).</p></HelpQuestion>
      </Section>
    </section>

    {/* Session X Part 11: what the Alpha can't do yet, in plain words. Each line is checked against the code or an owner decision. */}
    <Section id="known-limitations" updated="Nov 14, 2026" eyebrow="KNOWN LIMITATIONS" title="What the Alpha can&rsquo;t do yet">
      <ul className="help-list">
        <li><strong>Accounts and sync aren&rsquo;t open yet</strong> on alpha.zigoals.app. Until they are, what you enter stays in the browser or installed app you use, and only there. On an iPhone, <a className="text-link" href="#install">install ZIGoals</a> first and tap &ldquo;Keep my data on this device&rdquo;; <Link className="text-link" href="/app/settings#export-everything">Export everything</Link> gives you your own copy any time.</li>
        <li><strong>Reminders when ZIGoals is closed</strong> are opt-in, one device at a time (Settings &rarr; Reminders when closed), and need a signed-in account, so they wait for accounts too. Until then, due reminders show as cards on Today while ZIGoals is open.</li>
        <li><strong>Only staking moves ZIG, and only in your own wallet.</strong> Stake, unstake, move stake, claim rewards, governance votes and permission revokes are signed in Keplr after a review screen, on the practice network (no real value) or the real one, as you choose; ZIGoals never holds keys, nothing is bought, sold or sent by ZIGoals, and Wealth and Portfolio show what you enter and public data.</li>
        <li><strong>Prices</strong> come from CoinGecko and can be missing for a while; a missing price stays &ldquo;unknown&rdquo;, never zero.</li>
        <li><strong>ZIGi</strong> works with an AI you bring, or answers from your records on this device; the AI that ZIGoals would run for you isn&rsquo;t offered yet (<a className="text-link" href="#your-ai">ZIGi · Your Personal AI Companion</a>).</li>
        <li><strong>Devices and apps:</strong> Bluetooth works in Chrome and Edge, not on iPhone; Oura, Withings, Polar and Strava say &ldquo;Needs setup by ZIGoals&rdquo; until ZIGoals registers with them; Apple Health has no web access, so use its export; Fitbit&rsquo;s old connection ended on 30 October 2026, so ZIGoals no longer imports from Fitbit (what you brought in before stays).</li>
        <li><strong>Spotify</strong> needs a Spotify Premium account (Spotify’s own plan, not ZIGoals Premium), and connects for invited accounts only, for now.</li>
        <li><strong>Older copies of ZIGoals</strong> can&rsquo;t read what this one saves for sleep, meditation, your pages or links: they say so, keep it and change nothing.</li>
        <li><strong>Goals count in US dollars or euros.</strong> Accounts and assets keep any currency, each on its own; nothing is converted, so a holding in another currency doesn&rsquo;t count toward a Goal.</li>
        <li><strong>Photos stay on the device</strong> where you added them; another device shows the goal&rsquo;s colours. A backup carries them (<a className="text-link" href="#help-ab-photos">Do my photos sync?</a>).</li>
        <li><strong>After a new vault key,</strong> your extras wait until the device that synced them last syncs once; nothing is lost meanwhile.</li>
        <li><strong>Restore from a backup</strong> brings back your records and photos, not ZIGi&rsquo;s chats or settings, notifications or a timer in progress.</li>
        {/* Session AC (friends pack): three more, each pointing to its answer. */}
        <li><strong>Safari on iPhone and iPad</strong> offers no Home Screen shortcuts and no Share sheet entry for ZIGoals (<a className="text-link" href="#help-aa-home-screen">Home Screen shortcuts and sharing</a>).</li>
        <li><strong>Push notifications through an account are opt-in and need a signed-in account,</strong> so on this Alpha, where accounts aren&rsquo;t open yet, they reach no phone; notifications on this device need no account and are being switched on (below). Until then nothing reaches your phone while ZIGoals is closed; due reminders show on Today while it is open (<a className="text-link" href="#help-aa-reminders">Where are my reminders?</a>).</li>
        <li><strong>Your last backup isn&rsquo;t recorded:</strong> Settings &rarr; Your data says &ldquo;Not recorded&rdquo;, because making a backup writes nothing on this device; your browser&rsquo;s downloads list shows when you made one (<a className="text-link" href="#help-aa-data">Your data</a>).</li>
        {/* Session AF (ADR-028): the Checklist's and Earn's limits, each pointing to its answer. */}
        <li><strong>The Checklist stays on this device:</strong> your path, your own items and the day history aren&rsquo;t synced yet, so another device starts with an empty path (<a className="text-link" href="#help-af-checklist">What is the Checklist?</a>). It can travel as an optional, encrypted part of your sync once the sync service is updated.</li>
        <li><strong>Ecosystem apps open in their own tab:</strong> ZIGoals shows their live numbers and steps but never frames their sites, and signs nothing for them; only native staking signs, in your own wallet (<a className="text-link" href="#help-af-earn">What is the Earn page?</a>).</li>
        <li><strong>ZIGi never stakes, signs or moves money:</strong> a staking card only opens the review you complete in your own wallet (<a className="text-link" href="#help-af-earn-coach">What does ZIGi&rsquo;s Earn coach do?</a>).</li>
        <li><strong>Timeline times stay on this device;</strong> a habit&rsquo;s time goes to your other devices only when you choose &ldquo;Every day, on all my devices&rdquo;; a running fast or timer cannot be moved, and sleep, reminders and Checklist planets move on their own pages (<a className="text-link" href="#help-af-timeline">What is the Day timeline?</a>).</li>
        <li><strong>Add money opens the providers&rsquo; plain sites</strong> until ZIGoals has registered with them, so nothing is filled in for you yet; pairing a wallet by QR on a phone waits for the same step (<a className="text-link" href="#help-af-add-money">How do I add money?</a>).</li>
        {/* Session AJ (ADR-035): this session's limits, each pointing to its answer. */}
        <li><strong>Price alerts check only while ZIGoals is open;</strong> nothing reaches your phone yet (<a className="text-link" href="#help-aj-alerts">How do price alerts work?</a>).</li>
        <li><strong>A watched Bitcoin wallet shows its confirmed balance,</strong> read from mempool.space only (<a className="text-link" href="#help-aj-wealth">Watching by public key</a>).</li>
        <li><strong>Focus Sessions can&rsquo;t block other apps;</strong> time with the page hidden counts as away (<a className="text-link" href="#help-aj-guided">Focus Sessions</a>).</li>
        <li><strong>GPX and TCX runs:</strong> from this release, a run you import gets its pace and kilometre splits; runs imported before keep their summary, because their points were never kept (nothing is filled in after the fact). Files over 5 MB, or with anything but plain track data, are refused with the reason.</li>
        <li><strong>The food search waits for its service,</strong> which the owner switches on; foods from the Swiss database keep their source in their brand line.</li>
        {/* Session AK (ADR-036): this session's limits, each pointing to its answer. */}
        <li><strong>Notifications on this device are being switched on:</strong> you can set them up in Settings, and nothing reaches your phone until they are on for this Alpha (<a className="text-link" href="#help-ak-notify">How do notifications on this device work?</a>).</li>
        <li><strong>Barcode lookups and US foods need the food service too;</strong> the food library from the French and British tables works offline without it, and the Finnish Fineli table isn&rsquo;t in it yet (<a className="text-link" href="#help-ak-food">What changed in food logging?</a>).</li>
        <li><strong>Reading a label or estimating a meal from a photo needs your own AI</strong> connected to ZIGi; ZIGoals runs no AI for it (<a className="text-link" href="#help-ak-food">Photos and food</a>).</li>
        <li><strong>Grocery ticks stay on this device;</strong> another device starts with the list unticked (<a className="text-link" href="#help-ak-nutrition">The grocery list</a>).</li>
        <li><strong>Phone wallets by WalletConnect are being switched on,</strong> and staking with Keplr Mobile over WalletConnect hasn&rsquo;t been tried on a real phone yet; Keplr in the browser is the tested way to sign (<a className="text-link" href="#help-ak-wallets">Can I link a wallet on my phone?</a>).</li>
        <li><strong>Garmin workouts come in only as FIT files</strong> you export from Garmin; there is no Garmin connection (<a className="text-link" href="#help-ak-switch">Bring your data</a>).</li>
        {/* Session AL (PR-032, AL-HELP-006): Chess shows Lichess Blitz ratings and games, so the limit names what it is about: starting a game. */}
        <li><strong>A new Lichess game started from ZIGoals is rapid or classical only;</strong> Lichess doesn&rsquo;t let other apps start bullet or blitz games. Your blitz and bullet ratings and finished games are still read and shown in Chess (<a className="text-link" href="#help-ak-chess">Can I play Lichess inside ZIGoals?</a>).</li>
        {/* Session AK Part 13 (ADR-036): Studio-4's "to polish later" items that show in the app. */}
        <li><strong>ZIGi&rsquo;s hide move,</strong> when you dismiss its knock, always leaves to the right, and for a few frames its arm touches its body; too small to see at the app&rsquo;s sizes, and a smoother version is planned.</li>
        <li><strong>In a browser that can&rsquo;t play animated WebP,</strong> ZIGi&rsquo;s moves use a fallback at 12 frames a second, most with a harder outline.</li>
        <li><strong>A few of ZIGi&rsquo;s new moves aren&rsquo;t used yet:</strong> its glances (at the chat box, at you, at something on the page) and its hello without walking in; Meet ZIGi shows them all.</li>
        {/* Owner decision 6 (ADR-036): Earn's first load is accepted for this release, with its measurement. */}
        <li><strong>Earn takes a few seconds to settle on a slower phone:</strong> on a mid-range phone profile its first load kept the phone busy for about 3.9 seconds before every part answered at once.</li>
        {/* Owner decision 7 (ADR-036): seen once in CI's WebKit (Safari's engine); not reproduced in Chromium, where the box is never
            rebuilt and words typed across the switch stay. */}
        <li><strong>On Safari, words typed into ZIGi&rsquo;s box at the very moment it opens might be lost:</strong> if your own AI is set up, the box switches from answering on this device to your AI as its settings finish loading, in a split second; if what you typed disappears, type it again.</li>
        <li><strong>English only</strong> for now; numbers follow your device&rsquo;s language settings.</li>
      
        {/* Session AP (friends Alpha, 14 Nov): this release's honest limits. */}
        <li><strong>Weather isn&rsquo;t on.</strong> A weather service that would hide your address from the forecast provider is ready but not switched on in this Alpha, so nothing in ZIGoals reads the weather yet.</li>
        <li><strong>Mood tags, symptoms and run splits stay private like Health:</strong> ZIGi and NOVA can&rsquo;t read them in this version. They are in your exports and backups, and restore only when you choose Health.</li>
        <li><strong>The Bento view and the buttons that step aside are for computers;</strong> on a phone every page is already one column, and ZIGi, music and the Checklist live in Apps &amp; extras.</li>
        <li><strong>Someday tasks also show in Inbox and All,</strong> and the This evening and Someday lists show no counts in the menu yet.</li>
        <li><strong>The activity orbits are on Health only;</strong> they can&rsquo;t be added to Today as a widget yet.</li>
        <li><strong>Money insights need history:</strong> the usual-pace comparison needs three earlier months with entries, and the age of money a month of income and spending; until then they say so instead of guessing.</li>
</ul>
      <p className="fine">It&rsquo;s an Alpha: pages can change, and something may break. If it does, please <a className="text-link" href="#feedback">tell us</a>.</p>
    </Section>

    <Section id="feedback" updated="Nov 1, 2026 or earlier" eyebrow="SEND FEEDBACK" title="Tell us what you think">
      <SendFeedback/>
    </Section>
  </div>;
}
